/**
 * PERSONAJE DEL USUARIO CON HUESOS (modelo de Blender: static/usuario.glb).
 * Es un rig de Rigify: la malla esta pesada a los huesos DEF-* y, al exportar, las restricciones de Blender se
 * pierden, asi que cada hueso DEF se mueve a mano (como con el perro y el gato). Se animan solo el caminado y el
 * agacharse; la cabeza, la cara y las manos no se tocan (siguen al cuerpo).
 *
 *   loadPersonModel()                 carga el .glb (una vez)
 *   createPersonFromModel()           un personaje nuevo (grupo con userData.rig)
 *   updatePersonRig(group, dt)        mueve los huesos: lee userData.walking (caminar) y userData.crouch (0 de pie .. 1 agachado)
 *   personTuning / PERSON_DEFAULT     los valores que se ajustan en la pagina de depuracion
 * Nombres de huesos: three.js quita los puntos ("DEF-thigh.L" se usa como "DEF-thighL").
 */
import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import { clone } from 'three/examples/jsm/utils/SkeletonUtils.js'
import { damp } from '../../core/utils.js'

const MODEL_SCALE = 0.8 // el modelo mide 2.13: asi queda en 1.7 m
let source = null

export const hasPersonModel = () => !!source

export async function loadPersonModel() {
    try {
        const gltf = await new GLTFLoader().loadAsync(import.meta.env.BASE_URL + 'usuario.glb')
        source = gltf.scene
    } catch (error) {
        console.warn('No cargo static/usuario.glb: se usa el personaje de formas simples.', error)
        source = null
    }
}

// ---------------------------------------------------------------- colores
const COLORS = {
    skin: new THREE.Color('#f2c9a5'),
    shirt: new THREE.Color('#ff8a6f'),
    pants: new THREE.Color('#2b4c8c'),
    shoe: new THREE.Color('#f4f4f4'),
    hair: new THREE.Color('#5a3a2a'),
    brow: new THREE.Color('#3e281c'),
    eye: new THREE.Color('#1c2233'),
}
export const PERSON_COLORS = COLORS

// El modelo trae el cuerpo en piezas (todas con los mismos huesos). Las que tienen un solo color van lisas; las que
// mezclan (las piernas con los zapatos, los brazos con las mangas) se pintan por el hueso que mas pesa en cada vertice.
const FLAT = {
    torso: 'shirt',
    cabeza: 'skin',
    oreja_L: 'skin',
    oreja_R: 'skin',
    nariz: 'skin',
    pelo: 'hair',
    pantalon: 'pants', // la cintura del pantalon
    muslo_L: 'pants',
    muslo_R: 'pants',
    pantorrilla_L: 'skin', // el pantalon es corto: las pantorrillas se ven
    pantorrilla_R: 'skin',
    brazo_L: 'skin', // la manga ya es parte del torso
    brazo_R: 'skin',
    pie_L: 'shoe',
    pie_R: 'shoe',
    ceja_L: 'brow',
    ceja_R: 'brow',
    ojo_L: 'eye',
    ojo_R: 'eye',
}

/** Color de un vertice segun el hueso que mas pesa (para las piezas que mezclan colores). */
function zoneOf(name) {
    if (/^DEF-(foot|toe)/.test(name)) return 'shoe'
    if (/^DEF-(pelvis|thigh|shin)/.test(name)) return 'pants'
    if (/^DEF-(shoulder|upper_arm)/.test(name)) return 'shirt' // la manga
    return 'skin'
}

/**
 * Pesos mal pintados en el modelo: los vertices de la cintura de las piernas tienen peso de los huesos de los brazos
 * (los brazos cuelgan cerca de la cadera), asi que el pantalon se estira al balancear los brazos. Aqui, cada pieza solo
 * conserva los huesos que le corresponden; el peso que sobra se reparte entre los demas y, si no queda ninguno, pasa a
 * la cadera (DEF-spine).
 */
const BONES_OF = {
    pantalon: /^DEF-(spine|pelvis|thigh)/,
    muslo_L: /^DEF-(spine|pelvis|thigh|shin)/,
    muslo_R: /^DEF-(spine|pelvis|thigh|shin)/,
    pantorrilla_L: /^DEF-(thigh|shin|foot|toe)/,
    pantorrilla_R: /^DEF-(thigh|shin|foot|toe)/,
    pie_L: /^DEF-(shin|foot|toe)/,
    pie_R: /^DEF-(shin|foot|toe)/,
    torso: /^DEF-(spine|pelvis|shoulder|upper_arm|breast)/,
}
function cleanWeights(mesh) {
    const allowed = BONES_OF[mesh.name.replace(/_\d+$/, '')]
    if (!allowed) return
    const names = mesh.skeleton.bones.map((b) => b.name)
    const ok = names.map((n) => allowed.test(n))
    const hips = names.indexOf('DEF-spine')
    const geo = mesh.geometry.clone()
    const idx = geo.attributes.skinIndex
    const wgt = geo.attributes.skinWeight
    for (let i = 0; i < idx.count; i++) {
        let sum = 0
        for (let k = 0; k < 4; k++) {
            if (ok[idx.getComponent(i, k)]) sum += wgt.getComponent(i, k)
            else wgt.setComponent(i, k, 0)
        }
        if (sum > 1e-4) {
            for (let k = 0; k < 4; k++) wgt.setComponent(i, k, wgt.getComponent(i, k) / sum)
        } else {
            idx.setComponent(i, 0, hips)
            wgt.setComponent(i, 0, 1)
        }
    }
    geo.attributes.skinIndex.needsUpdate = true
    geo.attributes.skinWeight.needsUpdate = true
    mesh.geometry = geo
}
/**
 * Una pieza del modelo (las piernas) viene del reves: sus caras miran hacia adentro y se ve a traves del pantalon.
 * Se detecta por el volumen con signo de la malla (negativo = al reves) y se corrige girando los triangulos y las normales.
 */
function fixInsideOut(mesh) {
    const geo = mesh.geometry
    const pos = geo.attributes.position
    const index = geo.index ? geo.index.array : null
    if (!index) return
    const a = new THREE.Vector3()
    const b = new THREE.Vector3()
    const c = new THREE.Vector3()
    let volume = 0
    for (let f = 0; f < index.length; f += 3) {
        a.fromBufferAttribute(pos, index[f])
        b.fromBufferAttribute(pos, index[f + 1])
        c.fromBufferAttribute(pos, index[f + 2])
        volume += a.dot(b.cross(c)) / 6
    }
    if (volume >= 0) return
    const flipped = geo.clone()
    const idx = flipped.index.array
    for (let f = 0; f < idx.length; f += 3) {
        const tmp = idx[f + 1]
        idx[f + 1] = idx[f + 2]
        idx[f + 2] = tmp
    }
    flipped.index.needsUpdate = true
    const nor = flipped.attributes.normal
    for (let i = 0; i < nor.count; i++) nor.setXYZ(i, -nor.getX(i), -nor.getY(i), -nor.getZ(i))
    nor.needsUpdate = true
    mesh.geometry = flipped
}
/**
 * Las piezas de las piernas (cintura, muslos, pantorrillas y pies) vienen con los pesos revueltos y, como son piezas
 * separadas, al doblar la rodilla se abren huecos y el pantalon se estira. Aqui se les calculan pesos nuevos por
 * distancia a los huesos de las dos piernas: cada vertice se mueve con el hueso mas cercano y, cerca de una
 * articulacion, mezcla los dos. Como el calculo solo depende de donde esta el vertice, donde se tocan dos piezas
 * los pesos son iguales y no se separan. Arriba de la cadera el peso pasa a la pelvis (DEF-spine): la cintura
 * acompana al torso en vez de girar con el muslo.
 */
const LEG_PIECES = /^(pantalon|muslo_[LR]|pantorrilla_[LR]|pie_[LR])$/
const _bp = new THREE.Vector3()
const _seg = new THREE.Vector3()
const _toP = new THREE.Vector3()
function rebindLegs(mesh, inPlace = false) {
    const bones = mesh.skeleton.bones
    const by = (n) => bones.findIndex((b) => b.name === n)
    const origin = (i) => _bp.setFromMatrixPosition(mesh.skeleton.boneInverses[i].clone().invert()).clone() // en la pose de reposo
    // segmentos: hueso -> (inicio, fin) en el espacio de la malla
    const segments = []
    for (const s of ['L', 'R']) {
        const hip = origin(by(`DEF-thigh${s}`))
        const knee = origin(by(`DEF-shin${s}`))
        const ankle = origin(by(`DEF-foot${s}`))
        const toe = origin(by(`DEF-toe${s}`))
        const tip = toe.clone().add(toe.clone().sub(ankle).multiplyScalar(0.7)) // la punta del zapato
        segments.push(
            { bone: by(`DEF-thigh${s}`), a: hip, b: knee },
            { bone: by(`DEF-shin${s}`), a: knee, b: ankle },
            { bone: by(`DEF-foot${s}`), a: ankle, b: toe },
            { bone: by(`DEF-toe${s}`), a: toe, b: tip },
        )
    }
    const hipY = Math.max(...segments.map((s) => s.a.y))
    const spine = by('DEF-spine')
    const geo = inPlace ? mesh.geometry : mesh.geometry.clone()
    const pos = geo.attributes.position
    const idx = geo.attributes.skinIndex
    const wgt = geo.attributes.skinWeight
    let minY = Infinity
    let maxY = -Infinity
    for (let i = 0; i < pos.count; i++) {
        minY = Math.min(minY, pos.getY(i))
        maxY = Math.max(maxY, pos.getY(i))
    }
    const dist = (p, s) => {
        _seg.subVectors(s.b, s.a)
        const len2 = _seg.lengthSq() || 1e-9
        const u = Math.min(1, Math.max(0, _toP.subVectors(p, s.a).dot(_seg) / len2))
        return _toP.copy(s.a).addScaledVector(_seg, u).sub(p).length()
    }
    const p = new THREE.Vector3()
    // la cintura del pantalon (la caja de arriba) es una pieza rigida: se mueve entera con la pelvis para no estirarse
    const rigid = mesh.name.replace(/_\d+$/, '') === 'pantalon'
    for (let i = 0; i < pos.count; i++) {
        p.fromBufferAttribute(pos, i)
        if (rigid) {
            // la parte de abajo de la caja sigue a los muslos tanto como diga waistFollow (el resto va con la pelvis)
            const low = Math.min(1, Math.max(0, (maxY - p.y) / Math.max(1e-6, maxY - minY)))
            const follow = personTuning.waistFollow * low
            const thighs = segments.filter((s, n) => n % 4 === 0).map((s) => ({ bone: s.bone, w: 1 / (dist(p, s) + 0.02) ** 2 }))
            const tsum = thighs.reduce((acc, e) => acc + e.w, 0)
            const list = [{ bone: spine, w: 1 - follow }, ...thighs.map((e) => ({ bone: e.bone, w: (e.w / tsum) * follow }))]
            list.sort((a, b) => b.w - a.w)
            for (let k = 0; k < 4; k++) {
                idx.setComponent(i, k, list[k] ? list[k].bone : 0)
                wgt.setComponent(i, k, list[k] ? list[k].w : 0)
            }
            continue
        }
        // peso de cada hueso = 1 / (distancia + margen)^4: el mas cercano manda (la pieza casi no se estira) y solo en la
        // articulacion se mezclan dos huesos
        const raw = segments.map((s) => ({ bone: s.bone, w: 1 / (dist(p, s) + 0.02) ** 4 }))
        raw.sort((a, b) => b.w - a.w)
        const top = raw.slice(0, 3)
        const sum = top.reduce((acc, e) => acc + e.w, 0)
        // arriba de la cadera manda la pelvis
        const up = Math.min(1, Math.max(0, (p.y - (hipY - 0.13)) / 0.13))
        const spineW = up * up * (3 - 2 * up)
        const out = [...top.map((e) => ({ bone: e.bone, w: (e.w / sum) * (1 - spineW) })), { bone: spine, w: spineW }]
        out.sort((a, b) => b.w - a.w)
        for (let k = 0; k < 4; k++) {
            idx.setComponent(i, k, out[k] ? out[k].bone : 0)
            wgt.setComponent(i, k, out[k] ? out[k].w : 0)
        }
    }
    idx.needsUpdate = true
    wgt.needsUpdate = true
    if (!inPlace) mesh.geometry = geo
}
function paint(mesh) {
    fixInsideOut(mesh)
    if (LEG_PIECES.test(mesh.name.replace(/_\d+$/, ''))) rebindLegs(mesh)
    else cleanWeights(mesh)
    mesh.castShadow = true
    mesh.receiveShadow = true
    mesh.frustumCulled = false
    const key = mesh.name.replace(/_\d+$/, '') // three.js renombra la malla "torso" (igual que un hueso) como "torso_1"
    const flat = FLAT[key]
    if (flat) {
        mesh.material = new THREE.MeshStandardMaterial({ color: COLORS[flat], roughness: flat === 'eye' ? 0.3 : 0.8, metalness: 0 })
        return
    }
    const boneNames = mesh.skeleton.bones.map((b) => b.name)
    const geo = mesh.geometry.clone()
    const idx = geo.attributes.skinIndex
    const wgt = geo.attributes.skinWeight
    const colors = new Float32Array(geo.attributes.position.count * 3)
    for (let i = 0; i < geo.attributes.position.count; i++) {
        let best = 0
        for (let k = 1; k < 4; k++) if (wgt.getComponent(i, k) > wgt.getComponent(i, best)) best = k
        const c = COLORS[key === 'piernas' && !/^DEF-(foot|toe)/.test(boneNames[idx.getComponent(i, best)]) ? 'pants' : zoneOf(boneNames[idx.getComponent(i, best)])]
        colors.set([c.r, c.g, c.b], i * 3)
    }
    geo.setAttribute('color', new THREE.BufferAttribute(colors, 3))
    mesh.geometry = geo
    mesh.material = new THREE.MeshStandardMaterial({ vertexColors: true, roughness: 0.8, metalness: 0 })
}
// ---------------------------------------------------------------- ajustes
/** Valores que se ajustan en la pagina de depuracion (angulos en radianes, el signo decide el sentido). */
export const PERSON_DEFAULT = {
    // caminar
    walkSpeed: 6.6, // pasos por segundo (rapidez del ciclo)
    walkThigh: 0.35, // cuanto balancea el muslo (adelante y atras)
    walkKnee: 0.38, // cuanto dobla la rodilla al avanzar la pierna
    walkFoot: 0.26, // la punta del pie sube al avanzar
    walkArm: 0.5, // balanceo de los brazos
    walkElbow: 0.35, // codo doblado al caminar (mas al adelantar el brazo)
    walkBob: 0.012, // el cuerpo sube y baja con cada paso (m)
    walkLean: 0.06, // el torso se inclina un poco hacia adelante al caminar
    walkTwist: 0.1, // giro de los hombros al caminar
    // agacharse (con crouch = 1)
    crouchThigh: 1.3, // muslo hacia adelante
    crouchKnee: 2.3, // rodilla doblada
    crouchLean: 0.55, // el torso se inclina hacia adelante
    crouchSpine: 0.25, // curva extra de la espalda
    crouchArm: 0.5, // los brazos se adelantan para el equilibrio
    crouchSpeed: 5, // rapidez al agacharse y al levantarse (mas alto = mas rapido)
    // sentarse (con sit = 1): muslos horizontales y espinillas verticales, como en un sofa o una silla
    sitThigh: 1.5, // muslo hacia adelante
    sitKnee: 1.5, // rodilla doblada
    sitLean: 0.06, // el torso queda casi recto
    sitSpine: 0, // curva extra de la espalda
    sitArm: 0.45, // los brazos se adelantan hacia las piernas
    sitElbow: 0.5, // codo doblado
    sitSpeed: 4, // rapidez al sentarse y al levantarse
    floorOffset: 0,
    // la cintura del pantalon (la caja de arriba): 0 = rigida con la pelvis, 1 = su parte de abajo sigue a los muslos
    waistFollow: 0.78,
}
export const personTuning = { ...PERSON_DEFAULT }

// ---------------------------------------------------------------- creacion
const _v = new THREE.Vector3()
const _q = new THREE.Quaternion()
const _q2 = new THREE.Quaternion()
const _m = new THREE.Matrix4()
const AX = new THREE.Vector3(1, 0, 0)

/** Personaje con huesos. Se mueve con updatePersonRig(grupo, dt); el frente es +z y la altura 1.7 m. */
export function createPersonFromModel() {
    const group = new THREE.Group()
    const a = group.userData
    a.type = 'person'
    a.walking = false
    a.crouch = 0 // objetivo: 0 de pie .. 1 agachado
    a.sit = 0 // objetivo: 0 de pie .. 1 sentado
    a.armRaise = 0 // 0..1: estira el brazo derecho al frente (para abrir una puerta, saludar...)
    // el personaje de formas simples tenia piernas, brazos y mochila sueltos; los pasos antiguos todavia los leen: aqui son
    // objetos vacios (no hacen nada) y todo el movimiento va por walking / crouch / sit / armRaise
    const dummy = () => ({ rotation: { x: 0, y: 0, z: 0 } })
    Object.assign(a, { legL: dummy(), legR: dummy(), kneeL: dummy(), kneeR: dummy(), armL: dummy(), armR: dummy(), pack: { visible: true } })

    const model = clone(source)
    model.scale.setScalar(MODEL_SCALE)
    group.add(model)
    model.traverse((o) => o.isSkinnedMesh && paint(o))
    group.updateMatrixWorld(true)

    const bones = {}
    model.traverse((o) => {
        if (o.isBone) bones[o.name] = { bone: o, restQ: o.quaternion.clone(), restP: o.position.clone() }
    })
    // posicion de reposo de cada hueso en el espacio del grupo (para medir los pies y mantenerlos en el piso)
    const inv = group.matrixWorld.clone().invert()
    const world = (n) => _v.setFromMatrixPosition(bones[n].bone.matrixWorld).applyMatrix4(inv).clone()
    const worldQ = (n) => {
        bones[n].bone.getWorldQuaternion(_q)
        group.getWorldQuaternion(_q2)
        return _q2.invert().multiply(_q).clone() // orientacion de reposo respecto al grupo
    }
    for (const e of Object.values(bones)) e.restWQ = null
    const feet = ['DEF-footL', 'DEF-footR', 'DEF-toeL', 'DEF-toeR']
    a.rig = {
        bones,
        walk: 0,
        phase: 0,
        crouch: 0,
        drop: 0,
        shiftZ: 0,
        restFeetZ: (world('DEF-footL').z + world('DEF-footR').z) / 2,
        restLow: Math.min(...feet.map((n) => world(n).y)),
        feet: feet.map((n) => bones[n].bone),
        restWQ: {},
        manual: {},
        sit: 0,
        waist: null,
        t: Math.random() * 10, // reloj de la vida del personaje: respiracion, cabeza y parpadeo
        blink: 0,
        blinkLeft: 1.5 + Math.random() * 2,
        pendingDouble: false,
        gazeLeft: 0.5,
        gazeYaw: 0,
        gazeYawT: 0,
        gazePitch: 0,
        gazePitchT: 0,
        eyes: [],
        paused: false,
        info: {},
        model,
    }
    for (const n of ['DEF-footL', 'DEF-footR', 'DEF-toeL', 'DEF-toeR']) a.rig.restWQ[n] = worldQ(n)
    model.traverse((o) => {
        if (o.isSkinnedMesh && o.name.replace(/_\d+$/, '') === 'pantalon') a.rig.waist = o
        if (o.isSkinnedMesh && /^ojo_[LR]/.test(o.name)) a.rig.eyes.push(o) // se esconden un instante para parpadear
    })
    // datos de cada brazo para el alcance (reachArm): posiciones y direcciones de reposo en el espacio del grupo
    a.rig.arm = {}
    for (const side of ['L', 'R']) {
        const upper = bones[`DEF-upper_arm${side}`].bone
        const fore = bones[`DEF-forearm${side}`].bone
        const hand = bones[`DEF-hand${side}`].bone
        const P = (b) => world(b.name.replace(/\./g, ''))
        const s = P(upper)
        const e = P(fore)
        const h = P(hand)
        const inGroupQ = (b) => {
            b.getWorldQuaternion(_q)
            group.getWorldQuaternion(_q2)
            return _q2.invert().multiply(_q).clone()
        }
        if (side === 'R') a.rig.restShoulderR = s.clone()
        a.rig.arm[side] = {
            upper,
            fore,
            hand,
            L1: s.distanceTo(e),
            L2: e.distanceTo(h),
            dir: { upper: e.clone().sub(s).normalize(), fore: h.clone().sub(e).normalize() },
            restQ: { upper: inGroupQ(upper), fore: inGroupQ(fore), hand: inGroupQ(hand) },
        }
    }
    return group
}

/** Vuelve a calcular como sigue la cintura del pantalon a los muslos (personTuning.waistFollow), para ajustarlo en vivo. */
export function refitPersonWaist(group) {
    const mesh = group.userData.rig.waist
    if (!mesh) return
    rebindLegs(mesh, true)
    mesh.geometry.attributes.skinIndex.needsUpdate = true
    mesh.geometry.attributes.skinWeight.needsUpdate = true
}

// ---------------------------------------------------------------- animacion
/**
 * Rotacion de un hueso alrededor de un eje del mundo del personaje (x = de lado, y = arriba, z = al frente), sobre
 * la pose en que lo deja su padre. angle > 0 gira hacia atras la parte de abajo (las piernas) en x; asi, balanceo hacia
 * adelante = angulo negativo.
 */
function rotate(rig, group, name, angle, axis = AX) {
    const e = rig.bones[name]
    if (!e) return
    const b = e.bone
    b.parent.updateWorldMatrix(true, false)
    b.parent.getWorldQuaternion(_q) // padre en el mundo
    group.getWorldQuaternion(_q2)
    const parentInGroup = _q2.clone().invert().multiply(_q)
    const R = new THREE.Quaternion().setFromAxisAngle(axis, angle)
    // local = inv(padre) * R * padre * reposo
    b.quaternion.copy(parentInGroup).invert().multiply(R).multiply(parentInGroup).multiply(e.restQ)
}

/** Fija la orientacion absoluta de un hueso (respecto al personaje) = giro en x sobre su orientacion de reposo. */
function setAbsolute(rig, group, name, angle) {
    const e = rig.bones[name]
    const b = e.bone
    b.parent.updateWorldMatrix(true, false)
    b.parent.getWorldQuaternion(_q)
    group.getWorldQuaternion(_q2)
    const parentInGroup = _q2.clone().invert().multiply(_q)
    const target = new THREE.Quaternion().setFromAxisAngle(AX, angle).multiply(rig.restWQ[name])
    b.quaternion.copy(parentInGroup).invert().multiply(target)
}

/** Hace que un hueso (que en Blender seguia a otro por una restriccion) copie el movimiento del otro. */
function follow(rig, group, name, targetName) {
    const b = rig.bones[name]?.bone
    const t = rig.bones[targetName]?.bone
    if (!b || !t) return
    t.updateWorldMatrix(true, false)
    b.parent.updateWorldMatrix(true, false)
    _m.copy(b.parent.matrixWorld).invert().multiply(t.matrixWorld)
    _m.decompose(b.position, b.quaternion, _v.set(1, 1, 1))
    b.scale.set(1, 1, 1)
}

const pose = (rig, name, x = 0, y = 0, z = 0) => {
    const e = rig.bones[name]
    if (!e) return
    e.bone.quaternion.copy(e.restQ).multiply(_q.setFromEuler(new THREE.Euler(x, y, z)))
}

const LEG = ['L', 'R']

/**
 * Mueve los huesos cada cuadro. Lee group.userData.walking (camina), group.userData.crouch y group.userData.sit (objetivos de 0 a 1).
 * Despues de llamarla, rig.drop (m) y rig.shiftZ (m) dicen cuanto hay que bajar y mover hacia atras al personaje
 * para que los pies se queden en el piso al agacharse: los aplican quienes lo colocan (el modelo ya se mueve solo
 * dentro del grupo, ver rig.model).
 */
export function updatePersonRig(group, dt) {
    const a = group.userData
    const rig = a.rig
    const tn = personTuning
    if (rig.paused) {
        Object.values(rig.bones).forEach((e) => {
            e.bone.quaternion.copy(e.restQ)
            e.bone.position.copy(e.restP)
        })
        applyManual(rig)
        return
    }
    rig.walk = damp(rig.walk, a.walking && a.crouch < 0.3 && a.sit < 0.3 ? 1 : 0, 8, dt)
    if (a.walking) rig.phase += dt * tn.walkSpeed
    rig.crouch = damp(rig.crouch, a.crouch, tn.crouchSpeed, dt)
    rig.sit = damp(rig.sit, a.sit, tn.sitSpeed, dt)
    const W = rig.walk
    const C = rig.crouch
    const S = rig.sit
    const phase = rig.phase
    const s = Math.sin(phase)

    // ---- vida: respira, parpadea y mueve un poco la cabeza (mas quieta al caminar)
    rig.t += dt
    const t = rig.t
    const breath = Math.sin(t * 1.7) // inhala y exhala cada ~3.7 s
    const calm = 1 - 0.55 * W
    // mira a su alrededor: cada pocos segundos escoge un lugar (izquierda, derecha, arriba, abajo) y la cabeza se va hasta alla con suavidad
    rig.gazeLeft -= dt
    if (rig.gazeLeft <= 0) {
        rig.gazeLeft = 1.4 + Math.random() * 2.6
        rig.gazeYawT = (Math.random() * 2 - 1) * 0.8
        rig.gazePitchT = (Math.random() * 2 - 1) * 0.16
    }
    rig.gazeYaw = damp(rig.gazeYaw, rig.gazeYawT, 2.4, dt)
    rig.gazePitch = damp(rig.gazePitch, rig.gazePitchT, 2.4, dt)
    const look = 1 - 0.75 * W // al caminar mira mas al frente
    const headYaw = (Math.sin(t * 0.37) * 0.08 + Math.sin(t * 0.91 + 1.3) * 0.04) * calm + rig.gazeYaw * look
    const headPitch = (Math.sin(t * 0.53 + 2) * 0.04 + Math.sin(t * 1.3) * 0.015) * calm + rig.gazePitch * look
    const headRoll = Math.sin(t * 0.29 + 0.7) * 0.035 * calm
    rig.blinkLeft -= dt
    if (rig.blinkLeft <= 0) {
        rig.blink = 0.13 // los ojos se cierran un instante
        const again = !rig.pendingDouble && Math.random() < 0.18 // a veces parpadea dos veces seguidas
        rig.blinkLeft = again ? 0.25 : 2 + Math.random() * 3.5
        rig.pendingDouble = again
    }
    rig.blink = Math.max(0, rig.blink - dt)
    rig.eyes.forEach((eye) => (eye.visible = rig.blink <= 0))

    // ---- columna: la cadera y la espalda siguen la inclinacion (los huesos DEF-spine son una cadena aparte)
    const lean = W * tn.walkLean + C * tn.crouchLean + S * tn.sitLean
    const sway = W * 0.03 * s // la cadera se mece de lado con cada paso y los hombros lo compensan
    pose(rig, 'DEF-spine', lean * 0.45, -W * tn.walkTwist * s * 0.5, sway)
    const curve = C * tn.crouchSpine + S * tn.sitSpine
    pose(rig, 'DEF-spine001', lean * 0.2 + curve * 0.3 + breath * 0.006, 0, -sway * 0.4)
    pose(rig, 'DEF-spine002', lean * 0.15 + curve * 0.3 + breath * 0.012, W * tn.walkTwist * s * 0.4, -sway * 0.4)
    pose(rig, 'DEF-spine003', lean * 0.1 + curve * 0.2 + breath * 0.018, W * tn.walkTwist * s * 0.6, -sway * 0.3)
    // el cuello se endereza para que la cabeza siga mirando al frente (compensa casi toda la inclinacion de abajo)
    const total = lean * 0.95 + curve * 0.8
    pose(rig, 'DEF-spine004', lean * 0.05 - total * 0.75 + headPitch * 0.2, W * tn.walkTwist * s * 0.4 + headYaw * 0.2, sway * 0.5)
    // la cabeza gira poco a poco a los lados, asiente y se ladea; al caminar no sigue el giro de los hombros
    const counter = -W * tn.walkTwist * s * 1.2
    pose(rig, 'DEF-spine005', headPitch * 0.3, headYaw * 0.3 + counter * 0.4, headRoll * 0.4)
    pose(rig, 'DEF-spine006', headPitch * 0.5, headYaw * 0.5 + counter * 0.6, headRoll * 0.6)
    group.updateMatrixWorld(true)
    // los huesos que cuelgan de otra cadena siguen a la columna: las piernas (cadera), los brazos (pecho) y el cuello
    follow(rig, group, 'ORG-spine', 'DEF-spine')
    follow(rig, group, 'ORG-spine003', 'DEF-spine003')
    follow(rig, group, 'ORG-spine004', 'DEF-spine004')
    group.updateMatrixWorld(true)

    // ---- piernas
    LEG.forEach((side, i) => {
        const sign = i === 0 ? 1 : -1
        const ph = phase + (i === 0 ? 0 : Math.PI)
        const swing = Math.sin(ph) // + = pierna al frente
        const hip = -(W * tn.walkThigh * swing + C * tn.crouchThigh + S * tn.sitThigh) // negativo = adelante
        const forward = Math.max(0, Math.cos(ph)) // la pierna avanza
        const knee = W * tn.walkKnee * (0.12 + 0.88 * forward) + C * tn.crouchKnee + S * tn.sitKnee
        rotate(rig, group, `DEF-thigh${side}`, hip)
        group.updateMatrixWorld(true)
        rotate(rig, group, `DEF-shin${side}`, knee)
        group.updateMatrixWorld(true)
        // el pie se mantiene plano; al avanzar la pierna sube la punta
        // (al despegar el pie atras, la punta baja: el pie empuja el piso)
        setAbsolute(rig, group, `DEF-foot${side}`, -W * tn.walkFoot * forward + W * 0.2 * Math.max(0, -Math.cos(ph)))
        void sign
    })
    // ---- brazos: se balancean al reves que las piernas (las manos y los dedos no se tocan)
    LEG.forEach((side, i) => {
        const ph = phase + (i === 0 ? Math.PI : 0)
        const swing = Math.sin(ph)
        // parado, los brazos se mecen apenas con la respiracion y cada uno por su lado (nunca quedan congelados)
        const idle = (1 - W) * (1 - S)
        const drift = idle * (breath * 0.012 + Math.sin(t * 0.63 + i * 2.1) * 0.025)
        const arm = -(W * tn.walkArm * swing + C * tn.crouchArm + S * tn.sitArm + (side === 'R' ? a.armRaise * 1.3 : 0) + drift)
        rotate(rig, group, `DEF-upper_arm${side}`, arm)
        group.updateMatrixWorld(true)
        const elbow = -(W * tn.walkElbow * (0.5 + 0.5 * Math.max(0, Math.cos(ph))) + C * 0.2 + S * tn.sitElbow + idle * (0.1 + Math.sin(t * 0.8 + i) * 0.03))
        rotate(rig, group, `DEF-forearm${side}`, elbow)
    })
    group.updateMatrixWorld(true)

    applyManual(rig)
    if (a.postRig) a.postRig() // un paso puede mover los brazos despues (p. ej. cargar al perro: systems/carryDemo.js)

    // ---- piso: el cuerpo baja y se mueve hacia atras lo justo para que los pies sigan donde estaban
    const inv = group.matrixWorld.clone().invert()
    let low = Infinity
    let z = 0
    rig.feet.forEach((b, k) => {
        _v.setFromMatrixPosition(b.matrixWorld).applyMatrix4(inv)
        low = Math.min(low, _v.y)
        if (k < 2) z += _v.z / 2
    })
    // (se resta lo que el modelo ya se movio, para no medir dos veces)
    rig.drop = low - rig.model.position.y - rig.restLow - tn.floorOffset
    rig.shiftZ = z - rig.model.position.z - rig.restFeetZ
    rig.bob = W * tn.walkBob * Math.abs(Math.cos(phase))
    rig.model.position.y = -rig.drop + rig.bob * 0
    rig.model.position.z = -rig.shiftZ
    rig.info = { walk: W, crouch: C, sit: S, drop: rig.drop, shiftZ: rig.shiftZ }
}

/** Pose manual del panel de depuracion: { hueso: [x, y, z] } en radianes, sobre la pose de reposo. */
function applyManual(rig) {
    for (const [name, v] of Object.entries(rig.manual)) pose(rig, name, v[0], v[1], v[2])
}

// ---------------------------------------------------------------- brazo que alcanza un punto (la caricia)
/** Ajustes del brazo con el que se acaricia (se editan en la pagina de depuracion del usuario). */
export const ARM_DEFAULT = {
    shoulderX: 0.3, // donde queda el hombro respecto a la camara, en primera persona (m; x a la derecha, y arriba, z al frente es negativo)
    shoulderY: -0.28,
    shoulderZ: -0.12,
    restX: 0.34, // donde esta la mano antes de acariciar (abajo y afuera de la pantalla)
    restY: -1.0,
    restZ: -0.45,
    poleX: 0.4, // hacia donde apunta el codo (se dobla hacia abajo y afuera)
    poleY: -1,
    poleZ: 0.25,
    roll: -1.3, // giro de la mano sobre su eje (rad): -1.3 deja la palma hacia abajo
    patHeight: 0.07, // cuanto sube la mano en cada palmadita (m)
}
export const armTuning = { ...ARM_DEFAULT }

const _ap = new THREE.Vector3()
const _aq = new THREE.Quaternion()
const _as = new THREE.Vector3()
const _am = new THREE.Matrix4()
const _aq2 = new THREE.Quaternion()
function inGroup(group, obj, outPos, outQuat) {
    obj.updateWorldMatrix(true, false)
    _am.copy(group.matrixWorld).invert().multiply(obj.matrixWorld)
    _am.decompose(outPos, outQuat, _as)
}
/** Gira un hueso para que su direccion de reposo (restDir) apunte a dir (los dos en el espacio del grupo). */
function aimBone(group, bone, restDir, restQ, dir, roll = 0) {
    const desired = new THREE.Quaternion().setFromUnitVectors(restDir, dir).multiply(restQ)
    if (roll) desired.premultiply(new THREE.Quaternion().setFromAxisAngle(dir, roll))
    inGroup(group, bone.parent, _ap, _aq) // padre respecto al grupo
    bone.quaternion.copy(_aq).invert().multiply(desired)
    bone.updateWorldMatrix(false, true)
}

/**
 * Estira un brazo ("L" o "R") para que la mano llegue a target (en el espacio del grupo del personaje): cinematica
 * inversa de dos huesos (brazo y antebrazo). El codo se dobla hacia pole. Si el punto esta mas lejos de lo que
 * alcanza, el brazo se estira del todo hacia el.
 */
export function reachArm(group, side, target, { pole = null, roll = armTuning.roll } = {}) {
    const arm = group.userData.rig.arm[side]
    group.updateMatrixWorld(true)
    const shoulder = new THREE.Vector3()
    inGroup(group, arm.upper, shoulder, _aq2)
    const to = target.clone().sub(shoulder)
    const dist = Math.min(arm.L1 + arm.L2 - 1e-4, Math.max(Math.abs(arm.L1 - arm.L2) + 1e-4, to.length()))
    const u = to.normalize()
    const hint = pole || new THREE.Vector3(armTuning.poleX * (side === 'R' ? 1 : -1), armTuning.poleY, armTuning.poleZ)
    const perp = hint.clone().sub(u.clone().multiplyScalar(hint.dot(u))).normalize()
    // el codo: ley de los cosenos
    const a = (arm.L1 * arm.L1 - arm.L2 * arm.L2 + dist * dist) / (2 * dist)
    const h = Math.sqrt(Math.max(0, arm.L1 * arm.L1 - a * a))
    const elbow = shoulder.clone().addScaledVector(u, a).addScaledVector(perp, h)
    const hand = shoulder.clone().addScaledVector(u, dist)
    aimBone(group, arm.upper, arm.dir.upper, arm.restQ.upper, elbow.clone().sub(shoulder).normalize())
    const forward = hand.clone().sub(elbow).normalize()
    aimBone(group, arm.fore, arm.dir.fore, arm.restQ.fore, forward)
    aimBone(group, arm.hand, arm.dir.fore, arm.restQ.hand, forward, roll)
}

/**
 * El brazo derecho del personaje visto en primera persona (para acariciar): un personaje completo del que solo se
 * ve el brazo, colgado de un grupo que sigue a la camara. Devuelve { root, reach(puntoEnEspacioDeLaCamara) } o null.
 */
export function createFirstPersonArm() {
    if (!source) return null
    const person = createPersonFromModel()
    person.traverse((o) => {
        if (!o.isSkinnedMesh) return
        o.visible = /^brazo_R/.test(o.name) // solo el brazo derecho (y su mano)
    })
    person.userData.rig.eyes = [] // (no parpadea: los ojos no se ven)
    const root = new THREE.Group()
    root.add(person)
    const placeBody = () => {
        // el hombro derecho del modelo (en reposo) queda en armTuning.shoulder* respecto a la camara; el cuerpo mira hacia
        // adelante de la camara (-z): se gira media vuelta
        const shoulder = new THREE.Vector3()
        const rest = person.userData.rig.restShoulderR
        shoulder.copy(rest)
        person.rotation.y = Math.PI
        person.position.set(armTuning.shoulderX + shoulder.x, armTuning.shoulderY - shoulder.y, armTuning.shoulderZ + shoulder.z)
    }
    return {
        root,
        person,
        place: placeBody,
        reach(pointInRoot) {
            placeBody()
            person.updateMatrixWorld(true)
            reachArm(person, 'R', person.worldToLocal(root.localToWorld(pointInRoot.clone())))
        },
    }
}