    asiento: '#6fae9c',
    asiento001: '#6fae9c',
    computador: '#14305e',
    // cuadros: el marco gris y la lamina de color
    cuadro1: INTERIOR.frame,
    cuadro2: INTERIOR.frame,
    cuadro3: INTERIOR.frame,
    imagen: '#9fd0f2',
    imagen001: '#ffd9a0',
    imagen002: '#c9dbff',
    // cama: base de madera, colchon claro, sabana verde azulada y almohadas blancas
    base_madera: INTERIOR.wood,
    colchon: '#eef2f7',
    sabana: '#7cc8b6',
    almohada1: '#ffffff',
    almohada2: '#ffffff',
    // armario: el cuerpo, las dos hojas y la barra de las perchas
    armario: INTERIOR.woodLight,
    puerta1: INTERIOR.wood,
    puerta2: INTERIOR.wood,
    barra: '#b9c3d6',
    // la puerta del cuarto: marco y hoja
