const wardrobe = { k: 0, goal: 0 }
// Con el armario abierto, las dos hojas quedan perpendiculares: se vuelven obstaculos (con el armario cerrado ya lo es todo)
const DOOR_BLOCKS = [
    { x0: -1.9, x1: -1.1, z0: 1.25, z1: 1.45 },
    { x0: -1.9, x1: -1.1, z0: 2.8, z1: 2.98 },
]
function syncDoorBlocks() {
    const open = wardrobe.k > 0.4
    DOOR_BLOCKS.forEach((b) => {
        const at = world.colliders.indexOf(b)
        if (open && at < 0) world.colliders.push(b)
        else if (!open && at >= 0) world.colliders.splice(at, 1)
    })
}
/** Abre (true) o cierra (false) el armario; sin `instant` las hojas se mueven poco a poco (updateThirdRoom). */
export function openWardrobe(open, instant = false) {
    wardrobe.goal = open ? 1 : 0
    if (instant) {
        wardrobe.k = wardrobe.goal
        setWardrobe(wardrobe.k)
        syncDoorBlocks()
    }
}

// [piezas del .glb, cuanto se mueven (metros), cuanto se inclinan (radianes)] con el sismo al maximo
const SHAKE_PARTS = [
    [['taza'], 0.008, 0.09],
    [['computador'], 0.006, 0.03],
    [['silla'], 0.011, 0.045],
    [['asiento', 'asiento001'], 0.011, 0.04],
    [['cuadro1', 'imagen'], 0, 0.06],
    [['cuadro2', 'imagen001'], 0, 0.06],
    [['cuadro3', 'imagen002'], 0, 0.06],
    [['matera'], 0.004, 0.02],
    [['hojas'], 0.004, 0.05],
    [['materita'], 0.004, 0.02],
    [['hojitas'], 0.004, 0.07],
    // todo lo demas (menos las paredes, el piso y lo que se anima solo: las puertas y las hojas del armario), muy ligeramente
    [['escritorio'], 0.003, 0.006],
    [['mesa'], 0.004, 0.01],
    [['colchon', 'base_madera', 'sabana', 'almohada1', 'almohada2'], 0.003, 0.008], // la cama se mueve toda junta
    [['armario', 'barra', ...Array.from({ length: 13 }, (_, i) => 'gancho' + (i ? String(i).padStart(3, '0') : '')), ...Array.from({ length: 10 }, (_, i) => 'ropa' + (i ? String(i).padStart(3, '0') : ''))], 0.003, 0.006], // el armario con sus ganchos y su ropa
]
const shakers = []
let shakeClock = 0
let shakeWasOn = false

// ---- Cosas que se mueven de verdad en las misiones: la taza se corre un poquito por la mesa; un cuadro se suelta de una esquina y queda colgando de la otra ----
// (nada se cae. armFalls() al empezar una mision pone en marcha el reloj; resetFalls() lo pone todo de vuelta en su lugar)
const FALL = {
    taza: { lead: 'taza', kind: 'mug', start: 2 }, // segundos desde que empieza la mision
    cuadro2: { lead: 'cuadro2', kind: 'picture', start: 8 },
    imagen001: { lead: 'cuadro2', kind: 'picture', start: 8 },
}
const fallGroups = new Map() // lead -> { kind, start, lead (parte), parts: [{ part, p0, q0 }], dir, landed }
let fallArmed = false
let fallClock = 0
const ONE = new THREE.Vector3(0, 1, 0)
const qTmp = new THREE.Quaternion()
const smooth01 = (x) => {
    const k = Math.min(1, Math.max(0, x))
    return k * k * (3 - 2 * k)
}
export function armFalls() {
    resetFalls()
    fallArmed = true
}
export function resetFalls() {
    fallArmed = false
    fallClock = 0
    fallGroups.forEach((g) => {
        g.landed = false
        g.parts.forEach(({ part }) => {
            const s = shakers.find((x) => x.part === part)
            if (!s) return
            part.position.copy(s.basePos)
            part.rotation.copy(s.baseRot)
        })
    })
}
/** Pone la pieza en su pose de caida (mundo -> local del padre). offset en metros, qDelta = giro en el mundo alrededor del origen de la pieza. */
function placeFalling(g, offset, qDelta) {
    g.parts.forEach(({ part, p0, q0, parentInv }) => {
        part.position.copy(part.parent.worldToLocal(p0.clone().add(offset)))
        part.quaternion.copy(parentInv).multiply(qTmp.copy(qDelta).multiply(q0))
    })
}
const poseOffset = new THREE.Vector3()
const poseQuat = new THREE.Quaternion()
const poseQuat2 = new THREE.Quaternion()
const sideAxis = new THREE.Vector3()
/** Calcula y aplica la caida de un grupo en el segundo t (desde su inicio). */
function animateFall(g, t) {
    const { dir, p0y } = g
    sideAxis.crossVectors(dir, ONE).normalize() // eje horizontal paralelo a la pared: girar sobre el, con angulo +, voltea hacia arriba lo que mira a la habitacion
    poseOffset.set(0, 0, 0)
    poseQuat.identity()
    if (g.kind === 'mug') {
        // la taza se va corriendo muy poquito por la mesa (unos 6 cm), vibrando, y se queda ahi: no se cae
        poseOffset.addScaledVector(dir, 0.06 * smooth01(t / 6))
        poseQuat.setFromAxisAngle(sideAxis, Math.sin(t * 38) * 0.03 * smooth01(t / 0.8))
    } else {
        // cuadro: se suelta de una esquina y queda colgando de la otra, inclinado; primero se bambolea y se va calmando
        const angle = g.sign * (HANG_ANGLE * smooth01(t / 0.7) + 0.2 * Math.exp(-t * 1.4) * Math.sin(t * 9))
        poseQuat.setFromAxisAngle(dir, angle) // (en el plano de la pared, girando alrededor de la esquina que sigue sujeta)
        // el centro del cuadro gira alrededor de la esquina: se mueve lo que haga falta para que esa esquina no se despegue de la pared
        poseOffset.copy(g.center).sub(g.pivot).applyQuaternion(poseQuat).add(g.pivot).sub(g.center)
        if (!g.landed && t > 0.1) {
            g.landed = true
            audio.creak() // (el crujido de cuando se suelta)
        }
    }
    placeFalling(g, poseOffset, poseQuat)
}
const HANG_ANGLE = 0.65 // radianes (~37 grados) que queda inclinado el cuadro
/** Hace temblar un poco las piezas de SHAKE_PARTS segun la fuerza del sismo (quakeK, de 0 a ~0.7). Al terminar vuelven exactas a su lugar. */
function shakeFurniture(dt, quakeK) {
    if (!shakers.length) return
    if (quakeK < 0.002) {
        if (!shakeWasOn) return
        shakeWasOn = false
        shakers.forEach((s) => {
            s.part.position.copy(s.basePos)
            s.part.rotation.copy(s.baseRot)
        })
        return
    }
    shakeWasOn = true
    shakeClock += dt
    if (fallArmed && quakeK > 0.2) fallClock += dt
    const t = shakeClock * 34
    // las que ya empezaron a caerse (la taza, un cuadro) siguen su propia animacion
    const falling = new Set()
    if (fallArmed) {
        fallGroups.forEach((g) => {
            if (fallClock >= g.start) {
                animateFall(g, fallClock - g.start)
                g.parts.forEach(({ part }) => falling.add(part))
            }
        })
    }
    shakers.forEach((s) => {
        if (falling.has(s.part)) return
        // (cada pieza con su propio ritmo: los cuadros de un mismo par, que comparten fase, se mueven juntos)
        const a = t + s.phase
        s.part.position.set(
            s.basePos.x + Math.sin(a * 1.0) * s.pos * quakeK,
            s.basePos.y + Math.sin(a * 1.3 + 1) * s.pos * 0.4 * quakeK,
            s.basePos.z + Math.sin(a * 0.9 + 2) * s.pos * quakeK,
        )
        s.part.rotation.set(
            s.baseRot.x + Math.sin(a * 1.1 + 0.5) * s.rot * quakeK,
            s.baseRot.y + Math.sin(a * 0.8 + 1.5) * s.rot * quakeK,
            s.baseRot.z + Math.sin(a * 1.4) * s.rot * quakeK,
        )
    })
}
export function updateThirdRoom(dt, quakeK = 0) {
    shakeFurniture(dt, quakeK)
    if (wardrobe.k === wardrobe.goal) return
    const step = dt / 0.8 // tarda ~0.8 s en abrirse o cerrarse
    wardrobe.k += Math.sign(wardrobe.goal - wardrobe.k) * Math.min(step, Math.abs(wardrobe.goal - wardrobe.k))
    setWardrobe(wardrobe.k)
    syncDoorBlocks()
}
