export function layoutSizes(selected) {
    let t = showrooms.sizes,
        a = {
            large: -2.6,
            medium: 0,
            cat: 2.6,
        }
    ;['large', 'medium', 'cat'].forEach((o) => {
        let s = t[o],
            r = s.userData,
            i = t.baseS[o],
            n = selected === o
        s.visible = !selected || n
        let d = n ? 0 : a[o],
            u = n ? i * 1.45 : i
        placePet(s, d, 0, 0, n ? 0.3 : o === 'large' ? 0.5 : o === 'cat' ? -0.5 : 0, u)
    })
    t.shadow.position.x = 0
    t.shadow.scale.setScalar(selected ? 1.4 : 3.2)
}

/** Guarda todos los objetos dentro de la mochila (ocultos). */
export function resetKitItems() {
    const kit = showrooms.kit
    kit.open = 0
    kit.lidTarget = 0
    kit.intro = 1 // sin caida: la mochila ya esta sobre la mesa; solo la camara se acerca (ver steps.kit)
    kit.timelineOn = false // linea de tiempo del archivo de Blender (la tapa y los objetos)
    kit.items.forEach((item) => {
        item.userData.stage = 'in'
        item.userData.t = 0
        item.userData.sel = false
        item.userData.burstDone = false // para que vuelva a haber destello al salir
        item.userData.spin = 0
        item.visible = false
        item.scale.setScalar(0.001)
        item.position.copy(KIT_MOUTH)
    })
}
/**
 * Segundo propio de la animacion de un objeto: todos arrancan en el mismo instante (cuando el primero empieza en la linea de
 * tiempo del archivo), asi salen de la mochila a la vez en vez de uno tras otro.
 */
export const KIT_ITEM_SPEED = 0.28 // velocidad de la salida de los objetos (1 = la del archivo de Blender, 0.5 s por objeto; 0.28 = unos 1.8 s)
export const kitItemTime = (kit, anim) => anim.t0 + Math.max(0, kit.timeline - (kit.itemStart ?? anim.t0)) * KIT_ITEM_SPEED
/** Hace que los objetos salgan de la mochila (todos a la vez, justo cuando la tapa casi termina de abrirse). */
export function emergeKitItems(delay = 0.1) {
    // Con el modelo de Blender todo sigue la linea de tiempo del archivo: empieza en -delay y avanza a velocidad
    // normal; la tapa esta en su segundo exacto y los objetos salen juntos (ver kitItemTime).
    if (showrooms.kit.items.some((item) => item.userData.kitAnim)) {
        showrooms.kit.timeline = -delay
        showrooms.kit.timelineOn = true
        showrooms.kit.itemStart = Math.min(...showrooms.kit.items.map((item) => item.userData.kitAnim?.t0 ?? Infinity))
    }
    showrooms.kit.items.forEach((item, i) => {
        item.userData.stage = 'emerging'
        item.userData.t = -(delay + i * 0.35) / 0.9 // espera escalonada (sin el modelo de Blender)
    })
}
/** Abre (true) o cierra (false) la tapa de la mochila. */
export function setKitOpen(open) {
    showrooms.kit.lidTarget = open ? 1 : 0
}
/** Un objeto que ya se vio vuelve a la mochila. */
export function storeKitItem(index) {
    const item = showrooms.kit.items[index]
    const wasEmerging = item.userData.stage === 'emerging'
    item.userData.stage = 'storing'
    item.userData.t = 0
    item.userData.sel = false
    item.userData.from = item.position.clone()
    // con el modelo de Blender vuelve por el mismo camino de salida, al reves, desde donde esta
    if (item.userData.kitAnim) {
        const ka = item.userData.kitAnim
        // si aun estaba saliendo, vuelve desde el punto de la animacion en que iba (sin saltar al final)
        item.userData.stime = wasEmerging ? Math.min(ka.t1, Math.max(ka.t0, kitItemTime(showrooms.kit, ka))) : ka.t1
    }
}
