/**
 * MODELO 3D de la mano y el brazo del personaje (vista en primera persona).
 * Las unidades estan en metros y el origen es la palma; los dedos apuntan a -z (hacia adelante).
 */
import * as THREE from 'three'
import { cylinder, ellipsoid, place } from '../helpers.js'

const SKIN = '#f2c9a5'
const SLEEVE = '#ff8a6f'
// Direccion del antebrazo: hacia atras, abajo y a la derecha (sale por la esquina de la pantalla)
const ARM_DIR = new THREE.Vector3(0.55, -0.45, 0.72).normalize()

export function createHand() {
    const hand = new THREE.Group()
    // palma plana y cuatro dedos
    hand.add(ellipsoid(0.075, SKIN, 1, 0.42, 1.15))
    ;[-0.045, -0.015, 0.015, 0.045].forEach((x, i) => {
        const len = 1 - Math.abs(i - 1.5) * 0.12
        hand.add(place(ellipsoid(0.021, SKIN, 1, 0.9, 2.7 * len), x, 0, -0.105))
    })
    // pulgar
    const thumb = place(ellipsoid(0.023, SKIN, 1, 0.9, 2.2), 0.085, 0, -0.03)
    thumb.rotation.y = 0.6
    hand.add(thumb)
    // muneca y manga
    const up = new THREE.Vector3(0, 1, 0)
    const addSegment = (radius, from, length, color) => {
        const seg = cylinder(radius, radius, length, color, 14)
        seg.quaternion.setFromUnitVectors(up, ARM_DIR)
        seg.position.copy(ARM_DIR).multiplyScalar(from + length / 2)
        hand.add(seg)
    }
    // mano flotante: solo una muneca y un puno de manga cortos, sin brazo largo
    addSegment(0.034, 0.05, 0.07, SKIN)
    addSegment(0.052, 0.12, 0.1, SLEEVE)
    // la mano es totalmente opaca (sin transparencia); sin sombra propia para que no se vea doble
    hand.traverse((obj) => {
        if (obj.isMesh) obj.castShadow = false
    })
    return hand
}
