/**
 * EFECTO "AVANZAR" (warp): la imagen se acelera hacia el centro como un tunel de luz dorada.
 * Se dibuja encima de la escena: estelas que salen del centro, un brillo calido que crece y la escena que se
 * acerca desenfocada; al llegar al maximo se llama a onPeak() (aqui cambia de paso) y el efecto se va
 * desvaneciendo mientras la escena nueva vuelve a su tamano y a su nitidez.
 */
import { fovBoost } from '../systems/camera.js'
import { canvas as scene } from '../three/renderer.js'

const smooth = (x) => {
    const k = Math.min(1, Math.max(0, x))
    return k * k * (3 - 2 * k)
}

// colores del efecto: centro, medio, borde oscuro y estelas (r, g, b base + cuanto varia cada estela)
const PALETTES = {
    gold: { core: '255,234,184', mid: '255,190,100', deep: '118,60,14', edge: '12,6,2', streak: [255, 200, 130] },
    blue: { core: '238,248,255', mid: '96,176,255', deep: '22,70,150', edge: '6,18,48', streak: [170, 215, 255] },
}

/**
 * Nube: un cumulo de bolas suaves blancas con sombra azulada abajo, dibujado una vez en un canvas (varias formas).
 * Con ellas se arma el banco de nubes que tapa la pantalla y luego se abre y se disuelve, como en el video de referencia.
 */
let cloudSprites = null
function makeCloudSprites() {
    return Array.from({ length: 6 }, (_, v) => {
        const c = document.createElement('canvas')
        c.width = 320
        c.height = 220
        const g = c.getContext('2d')
        const balls = 15 + (v % 3) * 3
        for (let i = 0; i < balls; i++) {
            const bx = 60 + Math.random() * 200
            const by = 70 + Math.random() * 90 - Math.abs(bx - 160) * 0.18
            const br = 28 + Math.random() * 42
            const grad = g.createRadialGradient(bx, by, 0, bx, by, br)
            grad.addColorStop(0, 'rgba(255,255,255,0.62)')
            grad.addColorStop(0.55, 'rgba(250,253,255,0.3)')
            grad.addColorStop(1, 'rgba(250,253,255,0)')
            g.fillStyle = grad
            g.beginPath()
            g.arc(bx, by, br, 0, Math.PI * 2)
            g.fill()
        }
        // sombra azulada hacia abajo: da volumen al cumulo
        g.globalCompositeOperation = 'source-atop'
        const shade = g.createLinearGradient(0, 70, 0, 200)
        shade.addColorStop(0, 'rgba(170,200,235,0)')
        shade.addColorStop(1, 'rgba(150,185,228,0.55)')
        g.fillStyle = shade
        g.fillRect(0, 0, 320, 220)
        return c
    })
}

export function playWarp({ inTime = 1.3, outTime = 1.6, onPeak, color = 'gold' } = {}) {
    const pal = PALETTES[color] || PALETTES.gold
    const fx = document.createElement('canvas')
    fx.id = 'warpFx'
    document.body.appendChild(fx)
    const ctx = fx.getContext('2d')
    const dpr = Math.min(window.devicePixelRatio || 1, 1.5)
    fx.width = Math.round(innerWidth * dpr)
    fx.height = Math.round(innerHeight * dpr)
    const W = fx.width
    const H = fx.height
    const cx = W / 2
    const cy = H / 2
    const R = Math.hypot(cx, cy)
    // humo: nubes suaves que salen del centro hacia los bordes (angulo, distancia, velocidad, tamano, opacidad)
    const sprite = document.createElement('canvas')
    sprite.width = sprite.height = 128
    const sg = sprite.getContext('2d')
    const sgrad = sg.createRadialGradient(64, 64, 0, 64, 64, 64)
    sgrad.addColorStop(0, `rgba(${pal.core},0.9)`)
    sgrad.addColorStop(0.4, `rgba(${pal.mid},0.4)`)
    sgrad.addColorStop(1, `rgba(${pal.mid},0)`)
    sg.fillStyle = sgrad
    sg.fillRect(0, 0, 128, 128)
    const puffs = Array.from({ length: 90 }, () => ({
        a: Math.random() * Math.PI * 2,
        d: Math.random() * 0.5 * R,
        v: 0.25 + Math.random() * 0.55,
        s: 0.5 + Math.random() * 0.9,
        k: 0.5 + Math.random() * 0.5,
    }))
    // banco de nubes (solo en el azul): cada nube tiene su sitio, su tamano y su retraso al disolverse
    cloudSprites ||= makeCloudSprites()
    const clouds = Array.from({ length: color === 'blue' ? 60 : 0 }, (_, i) => {
        const big = i < 14
        const a = Math.random() * Math.PI * 2
        const dist = Math.sqrt(Math.random()) * R * 0.95
        return {
            sprite: cloudSprites[i % cloudSprites.length],
            x: cx + Math.cos(a) * dist,
            y: cy + Math.sin(a) * dist * 0.85,
            w: Math.max(W, H) * (big ? 0.5 + Math.random() * 0.3 : 0.26 + Math.random() * 0.26),
            dirX: Math.cos(a) + (Math.random() - 0.5) * 0.6,
            dirY: Math.sin(a) + (Math.random() - 0.5) * 0.6,
            delay: Math.random() * 0.9, // las nubes no se abren todas a la vez
            appear: Math.random() * 0.35,
        }
    })
    const t0 = performance.now()
    let peaked = false
    let last = t0
    const frame = (now) => {
        const dt = Math.min(0.05, (now - last) / 1000)
        last = now
        const t = (now - t0) / 1000
        const inK = Math.min(1, t / inTime) // 0 -> 1 al subir
        const outK = Math.max(0, (t - inTime) / outTime) // 0 -> 1 al bajar
        const power = inK < 1 ? smooth(inK) : (1 - smooth(outK)) ** 1.6 // la salida tiene una cola larga y suave // intensidad total del efecto
        if (!peaked && inK >= 0.9) { // el paso nuevo empieza a dibujarse un poco antes del maximo, ya tapado por el humo
            peaked = true
            if (onPeak) onPeak()
        }
        // la escena de abajo se acerca y se desenfoca con el efecto, y vuelve a la normalidad al terminar
        const zoom = 1 + 0.45 * power * power
        scene.style.transform = `scale(${zoom})`
        fovBoost.t = inK < 1 ? 0.55 * smooth(inK) : 0
        // dibujo
        ctx.globalCompositeOperation = 'source-over'
        ctx.clearRect(0, 0, W, H)
        // tunel: centro dorado y bordes oscuros calidos
        const glow = ctx.createRadialGradient(cx, cy, 0, cx, cy, R * (0.55 + 0.45 * power))
        glow.addColorStop(0, `rgba(${pal.core},${Math.min(1, 1.05 * power ** 1.1)})`)
        glow.addColorStop(0.22, `rgba(${pal.mid},${0.88 * power})`)
        glow.addColorStop(0.6, `rgba(${pal.deep},${0.78 * power})`)
        glow.addColorStop(1, `rgba(${pal.edge},${0.94 * power})`)
        ctx.fillStyle = glow
        ctx.fillRect(0, 0, W, H)
        // nubes de humo que salen del centro y se abren; cuanto mas fuerte el efecto, mas grandes, alargadas y rapidas
        ctx.globalCompositeOperation = 'source-over'
        const speed = (0.08 + 1.5 * power * power) * R
        puffs.forEach((p) => {
            p.d += p.v * speed * dt
            if (p.d > R * 1.05) p.d = Math.random() * 0.1 * R
            const near = p.d / R
            const size = (0.07 + 0.3 * near) * R * p.s * (0.55 + 0.75 * power)
            const fade = Math.min(1, near / 0.2) * (1 - near ** 2)
            ctx.save()
            ctx.translate(cx + Math.cos(p.a) * p.d, cy + Math.sin(p.a) * p.d)
            ctx.rotate(p.a)
            ctx.scale(1 + 1.3 * power, 1)
            ctx.globalAlpha = Math.max(0, 0.6 * power * fade * p.k)
            ctx.drawImage(sprite, -size, -size, size * 2, size * 2)
            ctx.restore()
        })
        // banco de nubes: tapa la pantalla al llegar al maximo y, al revelar la escena, se abre hacia los lados y se disuelve
        clouds.forEach((cl) => {
            let alpha
            let open = 0
            if (inK < 1) alpha = smooth((inK - 0.3 - cl.appear * 0.5) / 0.55)
            else {
                open = Math.min(1, Math.max(0, (outK * 1.7 - cl.delay) / 0.7))
                alpha = 1 - smooth(open)
            }
            if (alpha <= 0.01) return
            const drift = (open + 0.08 * outK) * 0.38 * R // al abrirse se apartan del centro
            const w = cl.w * (1 + 0.18 * (inK < 1 ? inK : 1) + 0.25 * open)
            const h = w * (220 / 320)
            ctx.globalAlpha = Math.min(1, alpha) * 0.92
            ctx.drawImage(cl.sprite, cl.x + cl.dirX * drift - w / 2, cl.y + cl.dirY * drift - h / 2, w, h)
        })
        ctx.globalAlpha = 1
        if (t < inTime + outTime) requestAnimationFrame(frame)
        else {
            fx.remove()
            scene.style.transform = ''
            fovBoost.t = 0
        }
    }
    requestAnimationFrame(frame)
}
