/**
 * HUD: fondo por ambiente, temporizador, objetivo actual.
 */
import * as THREE from 'three'
import { clamp, isTouch, qs, qsa } from '../core/utils.js'
import { camera } from '../three/renderer.js'
import { cleanCam } from '../systems/camera.js'
import { content } from '../data/content.js'

export function setBackground(name) {
    qsa('#bg i').forEach((t) => t.classList.toggle('on', t.dataset.bg === name))
}
export function showTimer(visible) {
    qs('#timer').hidden = !visible
}
export function updateTimer(remaining, total) {
    let a = qs('#timer')
    a.querySelector('b').textContent = Math.max(0, Math.ceil(remaining))
    a.querySelector('u').style.transform = 'scaleX(' + clamp(remaining / total, 0, 1) + ')'
    a.classList.toggle('low', remaining <= 5)
}
export function setObjective(title, subtitle) {
    let a = qs('#objective')
    if (!title) {
        a.hidden = true
        return
    }
    qs('strong', a).textContent = title
    qs('small', a).textContent = subtitle || ''
    qs('small', a).hidden = !subtitle
    a.hidden = false
}

// ---- Recorrido por scroll: indicador, barra de progreso, vineta y titulo del objeto ----
/** Muestra u oculta la ayuda "Desplazate para avanzar" y la barra de progreso lateral. */
let hintScrolled = false // el usuario ya hizo scroll: la ayuda no vuelve al centro
export function showScrollHint(visible, later = false) {
    const hint = qs('#scrollHint')
    hint.hidden = !visible || later // later: la barra lateral aparece ya y la ayuda despues (showCenteredScrollHint)
    hintScrolled = false
    lastScrollReady = null // se vuelve a calcular en el siguiente cuadro
    hint.classList.remove('quiet', 'center', 'nudge', 'ready', 'wait')
    qs('b', hint).textContent = isTouch ? content.scroll.hintTouch : content.scroll.hint
    qs('#tourRail').hidden = !visible
}
/** La ayuda de scroll aparece en el centro de la pantalla; al primer scroll baja a su lugar de siempre. */
export function showCenteredScrollHint() {
    if (hintScrolled) return
    const hint = qs('#scrollHint')
    hint.hidden = false
    hint.classList.add('center')
}
/** Ayuda de movimiento (abajo, al centro): aparece y se va desvaneciendo sola, como la del scroll. */
export function showMoveHint() {
    const el = qs('#moveHint')
    const text = content.controls
    // (interactuar es solo con el clic en "Revisar": no hay tecla E)
    el.innerHTML = '<span class="hl">' + (isTouch ? text.touch : text.click) + '</span>'
    el.hidden = false
    el.classList.remove('on')
    void el.offsetWidth // reinicia la transicion
    el.classList.add('on') // aparece con un fundido y se queda justo debajo de la habitacion (placeMoveHint) hasta que termina la mision
    placeMoveHint()
}
const roomPoint = new THREE.Vector3()
const ROOM_FRONT_CORNERS = [
    [2.46, 2.99],
    [2.46, -2.99],
    [-2.46, 2.99],
]
/** Pone la ayuda de movimiento justo debajo de la habitacion (la camara de las misiones es fija: su lugar no cambia). */
const steadyCamera = new THREE.PerspectiveCamera()
export function placeMoveHint() {
    const el = qs('#moveHint')
    if (el.hidden) return
    // se mide con la camara SIN el temblor del sismo: asi la ayuda se queda quieta aunque todo lo demas se sacuda
    steadyCamera.fov = camera.fov
    steadyCamera.aspect = camera.aspect
    steadyCamera.near = camera.near
    steadyCamera.far = camera.far
    steadyCamera.position.copy(cleanCam.position)
    steadyCamera.quaternion.copy(cleanCam.quaternion)
    steadyCamera.updateProjectionMatrix()
    steadyCamera.updateMatrixWorld(true)
    let lowest = 0
    for (const [x, z] of ROOM_FRONT_CORNERS) {
        roomPoint.set(x, 0, z).project(steadyCamera)
        lowest = Math.max(lowest, (-roomPoint.y * 0.5 + 0.5) * innerHeight)
    }
    el.style.bottom = 'auto'
    el.style.top = Math.min(innerHeight - el.offsetHeight - 10, lowest + 38) + 'px' // (~1 cm mas abajo que antes: no choca con el cuadro de texto de arriba)
}
export function hideMoveHint() {
    const el = qs('#moveHint')
    el.hidden = true
    el.classList.remove('on')
    el.style.top = el.style.bottom = ''
}
/** La ayuda se atenua en cuanto el usuario empieza a avanzar. */
export function quietScrollHint() {
    hintScrolled = true
    qs('#scrollHint').classList.remove('center', 'nudge') // baja a su lugar de siempre
    qs('#scrollHint').classList.add('quiet')
}
/** Si lleva unos segundos sin hacer scroll, la ayuda vuelve a verse completa y late para recordar que se puede avanzar. */
export function remindScrollHint() {
    const hint = qs('#scrollHint')
    if (hint.hidden || hint.classList.contains('nudge')) return
    hint.classList.remove('quiet')
    hint.classList.add('nudge')
}
/** Indicador de scroll: "ready" cuando ya se puede avanzar (aparece con un destello); mientras esta bloqueado se esconde. */
let lastScrollReady = null
export function setScrollReady(ready) {
    if (ready === lastScrollReady) return
    lastScrollReady = ready
    const hint = qs('#scrollHint')
    hint.classList.toggle('ready', ready)
    hint.classList.toggle('wait', !ready)
}
const VIGNETTE_BASE = 0.4 // (era 0.6: oscurecia los bordes de la sala encima de la luz 3D) // opacidad de la vineta cuando no hay nada cerca (0 = sin vineta, 0.9 = la de cuando se llega a un objeto)
/** progress: 0..1 del camino. closeness: 0..1 al acercarse al objeto. */
export function setTourProgress(progress, closeness) {
    qs('#tourRail i').style.transform = 'scaleY(' + progress.toFixed(3) + ')'
    // la vineta de los bordes siempre esta (leve) de principio a fin y se cierra un poco mas al acercarse a un objeto
    qs('#vignette').style.opacity = (VIGNETTE_BASE + closeness * (0.9 - VIGNETTE_BASE)).toFixed(3)
    qs('#scrollHint').classList.toggle('gone', closeness > 0.85)
}
/** Indicacion (titulo y subtitulo) arriba: aparece de golpe, con un fundido suave (sin efecto de maquina de escribir). */
export function showStopLabel(title, sub, plain = false) {
    const el = qs('#stopLabel')
    resetStopLabel()
    el.classList.toggle('plain', !!plain) // plain: solo texto, arriba al centro, sin recuadro
    el.classList.toggle('left', plain === 'left') // 'left': solo texto, arriba a la izquierda
    el.classList.toggle('right', plain === 'right') // 'right': solo texto, arriba sobre la columna de la derecha
    qs('h2', el).textContent = title
    qs('p', el).textContent = sub
    el.hidden = false
    void el.offsetWidth // reinicia el fundido
    el.classList.add('shown')
}
let stopLabelTimer = null
/** Quita la indicacion al instante (la usa showStopLabel antes de poner la siguiente). */
function resetStopLabel() {
    const el = qs('#stopLabel')
    clearTimeout(stopLabelTimer)
    el.hidden = true
    el.classList.remove('shown', 'out')
    qs('h2', el).textContent = ''
    qs('p', el).textContent = ''
}
/** La indicacion se desvanece con suavidad (y despues se quita). */
export function fadeStopLabel(ms = 700) {
    const el = qs('#stopLabel')
    if (el.hidden || el.classList.contains('out')) return
    el.classList.remove('shown')
    el.style.setProperty('--out', ms + 'ms')
    el.classList.add('out')
    clearTimeout(stopLabelTimer)
    stopLabelTimer = setTimeout(resetStopLabel, ms)
}
/** Las indicaciones siempre se van desvaneciendose, no de golpe. */
export function hideStopLabel() {
    fadeStopLabel(600)
}