/**
 * "CUIDA SUS PATAS" (pantalla de tamanos): la mascota levanta una pata delantera, con la almohadilla hacia la camara, y la camara se acerca
 * a ella (sizes.js mueve la camara hacia `target`, que sigue a la pata). Usa la pose manual del rig de la mascota (rig.manual).
 *
 *   createPawDemo({ pet, kind: 'dog' | 'cat' })  ->  { play(), update(dt), dispose(), active, target }
 */
import * as THREE from 'three'

// Angulos (radianes, sobre la pose de reposo) de los huesos de la pata levantada: se llegan poco a poco desde 0
const PAW = {
    dog: {
        // la pata sube estirada hacia adelante y la mano se dobla hacia arriba: la almohadilla mira a la camara (como al dar la pata)
        'ORG-front_thighR': [-1.35, 0, 0],
        'ORG-front_shinR': [0.35, 0, 0],
        'ORG-front_footR': [-2.9, 0, 0],
    },
    cat: {
        'ORG-upper_armL': [-1.05, 0, 0],
        'ORG-forearmL': [1.35, 0, 0],
        'ORG-handL': [0.9, 0, 0],
    },
}
// Pose de la pata levantada del perro, editable en vivo con F2 (ui/walkTuner.js; se guarda en el navegador): angulos en radianes de cada hueso
export const PAW_DEFAULT = { thigh: -1.1, thighTwist: 0.14, thighSide: -0.12, shin: -0.22, foot: -0.2, footTwist: 0, footSide: 0 }
export const pawTuning = { ...PAW_DEFAULT }
if (import.meta.env.DEV) {
    // (los ajustes guardados solo se leen en desarrollo: quien visita la pagina siempre ve los valores de arriba)
    try {
        Object.assign(pawTuning, JSON.parse(localStorage.getItem('petalert.paw') || '{}'))
    } catch (e) {}
}
export const savePawTuning = () => {
    try {
        localStorage.setItem('petalert.paw', JSON.stringify(pawTuning))
    } catch (e) {}
}
const dogPose = () => ({
    'ORG-front_thighR': [pawTuning.thigh, pawTuning.thighTwist, pawTuning.thighSide],
    'ORG-front_shinR': [pawTuning.shin, 0, 0],
    'ORG-front_footR': [pawTuning.foot, pawTuning.footTwist, pawTuning.footSide],
})

const FOOT = { dog: 'ORG-front_footR', cat: 'ORG-handL' } // el hueso cuya posicion sigue la camara

const ease = (x) => {
    const k = Math.min(1, Math.max(0, x))
    return k * k * (3 - 2 * k)
}

export function createPawDemo({ pet, kind }) {
    const poseNow = () => (kind === 'dog' ? dogPose() : PAW[kind] || PAW.dog) // (la del perro se lee de pawTuning cada cuadro)
    const demo = { active: false, time: 0, target: new THREE.Vector3(), k: 0 }
    const rig = () => pet.userData.rig

    demo.play = () => {
        demo.active = true
        demo.time = 0
        demo.k = 0
    }

    demo.update = (dt) => {
        if (!demo.active) return
        demo.time += dt
        demo.k = ease(demo.time / 0.9)
        const r = rig()
        if (!r?.manual) return
        Object.entries(poseNow()).forEach(([bone, angles]) => (r.manual[bone] = angles.map((a) => a * demo.k)))
        const foot = r.bones?.[FOOT[kind]]?.bone
        if (foot) {
            pet.updateMatrixWorld(true)
            foot.getWorldPosition(demo.target)
        }
    }

    /** La pata vuelve a su lugar. */
    demo.dispose = () => {
        if (!demo.active) return
        demo.active = false
        const r = rig()
        if (r?.manual) Object.keys(poseNow()).forEach((bone) => delete r.manual[bone])
    }
    return demo
}

/**
 * Editor en pantalla de la pata levantada (abajo a la izquierda): se abre solo en la nota "Cuida sus patas" cuando se desarrolla
 * (npm run dev) o si la direccion lleva ?editar. Mueve los valores de pawTuning al instante; "Copiar" deja los numeros en el portapapeles.
 * Devuelve una funcion que lo quita.
 */
export function openPawEditor() {
    if (!import.meta.env.DEV && !/[?&]editar/.test(location.search)) return () => {}
    const FIELDS = [
        ['thigh', 'Muslo (sube la pata)', -2.2, 0.8],
        ['thighTwist', 'Muslo: giro (rotar)', -1.6, 1.6],
        ['thighSide', 'Muslo: ladeo (abrir hacia un lado)', -1.6, 1.6],
        ['shin', 'Canilla (dobla la pata)', -1.2, 2.2],
        ['foot', 'Pie (sube o baja la punta)', -4, 2],
        ['footTwist', 'Pie: giro', -1.6, 1.6],
        ['footSide', 'Pie: ladeo', -1.6, 1.6],
    ]
    const box = document.createElement('div')
    box.id = 'pawEditor'
    box.style.cssText =
        'position:fixed;left:14px;bottom:14px;z-index:9998;width:270px;padding:10px 12px;border-radius:12px;background:rgba(14,20,34,.93);color:#e8eefc;font:12px/1.4 system-ui,sans-serif;box-shadow:0 8px 30px rgba(0,0,0,.4)'
    box.innerHTML = '<b style="font-size:13px">Pata levantada</b><small style="display:block;color:#93a3c6;margin-bottom:4px">Mueve los valores y mira al perro</small>'
    const outputs = []
    FIELDS.forEach(([key, label, min, max]) => {
        const row = document.createElement('label')
        row.style.cssText = 'display:flex;justify-content:space-between;margin-top:6px;color:#b9c6e4'
        const out = document.createElement('output')
        out.style.color = '#ffc24d'
        row.innerHTML = `<span>${label}</span>`
        row.appendChild(out)
        const input = document.createElement('input')
        Object.assign(input, { type: 'range', min, max, step: 0.02, value: pawTuning[key] })
        input.style.cssText = 'width:100%'
        const show = () => (out.textContent = (+pawTuning[key]).toFixed(2))
        input.addEventListener('input', () => {
            pawTuning[key] = +input.value
            show()
            savePawTuning()
        })
        show()
        outputs.push(() => {
            input.value = pawTuning[key]
            show()
        })
        box.append(row, input)
    })
    const button = (text, fn) => {
        const b = document.createElement('button')
        b.textContent = text
        b.style.cssText = 'margin:8px 6px 0 0;padding:4px 9px;border-radius:6px;border:1px solid #3e507a;background:#2a3856;color:#fff;cursor:pointer'
        b.addEventListener('click', fn)
        return b
    }
    box.append(
        button('Copiar valores', () => navigator.clipboard && navigator.clipboard.writeText(JSON.stringify(pawTuning, null, 2))),
        button('Restablecer', () => {
            Object.assign(pawTuning, PAW_DEFAULT)
            outputs.forEach((fn) => fn())
            savePawTuning()
        }),
    )
    // el panel no debe girar la camara ni pasar el scroll al recorrido
    box.addEventListener('pointerdown', (e) => e.stopPropagation())
    document.body.appendChild(box)
    return () => box.remove()
}