/**
 * PASOS: Inicio -> Introduccion animada (start) -> entrada a la casa (walk, en before.js).
 */
import * as THREE from 'three'
import { audio } from '../audio/audio.js'
import { session, state } from '../core/state.js'
import { qs } from '../core/utils.js'
import { content } from '../data/content.js'
import { goTo, steps } from './navigation.js'
import { fovBoost, setCameraMode, setOrbit } from '../systems/camera.js'
import { lockTour, startTour, tour } from '../systems/scrollTour.js'
import { cat, dog, groomPet, placePet, popIn, setPetMood } from '../three/characters.js'
import { livingRoom, setDoorOpen } from '../three/livingRoom.js'
import { camera, lightDim, mainScene } from '../three/renderer.js'
import { world } from '../three/world.js'
import { setBackground } from '../ui/hud.js'
import { showDynamic, showPanel } from '../ui/panels.js'
import { addHotspot } from '../ui/hotspots.js'

/**
 * INICIO: la entrada de la casa (donde empieza la experiencia: la reja, la puerta y la acera de baldosa roja) vista desde la acera. Cacao y Nube
 * esperan juntos en la entrada, junto a la reja. La entrada queda en el lado izquierdo de la pantalla y el texto en el derecho. Al cargar, la
 * camara empieza un poco mas atras y se acerca hasta la vista de la portada.
 */
// La casa mira a la calle (+x): la puerta esta en x 3.46, z -2, y la reja del frente en x 6 (con el hueco de la entrada frente a la puerta).
const HOME_ENTRY = { x: 5.4, z: -2.0, ty: 0.3 } // el punto que mira la camara: la entrada, entre la reja y la puerta (la camara mira hacia -x)
const HOME_FINAL = { r: 2.95, h: 0.7 } // camara de la portada: a r metros de la entrada, sobre la acera, y a h de altura
const HOME_START = { r: 4.4, h: 1.25 } // desde donde empieza a acercarse
const HOME_DIM = 1 // las luces del dia en el inicio (1 = igual que en el resto de la pagina)
const HOME_SIDE = 0.5 // las mascotas quedan a esta fraccion del ancho de la pantalla hacia la izquierda del centro (-1 = borde)
const PETS_SPAN = 1.1 // metros que ocupan Cacao y Nube juntos
const HOME_SPAN = 0.42 // fraccion del ancho de la pantalla que ocupan (pantalla ancha)
const HOME_FOV = 0.45 // campo de vision extra (fovBoost, en fracciones de 26 grados)
const HOME_FOV_NARROW = 0.5 // en pantallas angostas (celular) el texto va centrado y las mascotas arriba: hace falta abrir mas la vista
const isNarrow = () => innerHeight > innerWidth || (innerWidth <= 900 && innerHeight > 520) // (igual que el @media de css/08-inicio.css; un celular acostado usa el diseno ancho)
const HOME_DOLLY = 6.6 // segundos que tarda en acercarse (todo el tiempo de la presentacion del logo)
const HOME_DELAY = 0.5 // espera inicial (mientras se va la pantalla de carga)
// Entrada: primero el logo solo en el centro (con su frase), luego sube a su lugar; recien entonces la sala se llena: aparece Cacao y
// despues Nube, cada uno con un salto y una onda de luz. (El tiempo de aqui cuenta desde que empieza el acercamiento, medio segundo
// despues que el de css/08-inicio.css, donde el logo llega arriba a los 6.1 s y el texto empieza a los 6.5 s)
const HOME_DOG_AT = 5.7
const HOME_CAT_AT = 6.4
// Ya con el texto en pantalla, Cacao y Nube se entretienen entre ellos en una vuelta que se repite
const HOME_PLAY_FROM = 8.2
// Presentacion del logo: donde queda en el centro de la pantalla (fraccion del alto) y que tan chico es respecto a su tamano final
const LOGO_CENTER_Y = 0.42
const LOGO_START_SCALE = 0.96
const HOME_PLAY_EVERY = 14 // segundos de una vuelta completa
// Cacao y Nube juntos en la entrada (uno junto al otro, en z), de cara a la camara (hacia +x). Cacao a la izquierda de la pantalla (z mayor).
const HOME_DOG = { x: 5.5, z: -1.72, scale: 0.45 }
const HOME_CAT = { x: 5.5, z: -2.3, scale: 0.43 }
const FACE_STREET = Math.PI / 2 // rotacion en y para mirar hacia +x (la calle, donde esta la camara)
const homeWorld = { group: null, rings: [] }
const homeEase = (k) => 1 - Math.pow(1 - Math.min(1, Math.max(0, k)), 3) // frena suave al llegar

/** Grupo donde van las ondas de luz de la entrada de las mascotas; se crea una sola vez. */
function buildHomeWorld() {
    if (homeWorld.group) return homeWorld
    homeWorld.group = new THREE.Group()
    mainScene.add(homeWorld.group)
    return homeWorld
}

/** Altura del piso de la entrada (se mmide con un rayo hacia abajo), para que Cacao y Nube queden sobre el piso, sin hundirse ni flotar. */
function entranceY() {
    livingRoom.root.updateMatrixWorld(true)
    const ray = new THREE.Raycaster(new THREE.Vector3(HOME_DOG.x, 2, (HOME_DOG.z + HOME_CAT.z) / 2), new THREE.Vector3(0, -1, 0))
    const hit = ray.intersectObject(livingRoom.root, true)[0]
    return hit && hit.point.y > -0.05 && hit.point.y < 0.7 ? hit.point.y : 0
}

/** Pone a Cacao (a la izquierda de la pantalla) y a Nube juntos en la entrada, mirando a la camara. */
function layoutHomePets() {
    const y = entranceY()
    placePet(dog, HOME_DOG.x, y, HOME_DOG.z, FACE_STREET - 0.15, HOME_DOG.scale)
    placePet(cat, HOME_CAT.x, y, HOME_CAT.z, FACE_STREET + 0.15, HOME_CAT.scale)
}
/**
 * Mide donde queda el logo en la portada (su lugar definitivo) y pone en #home las variables que usa la animacion de css/08-inicio.css:
 * --lx y --ly (cuanto hay que correrlo para que quede en el centro de la pantalla), --ls (su escala al empezar) y --tagY (donde va la frase).
 * Solo cambia variables de CSS: el logo, sus textos y su diseno son los de siempre.
 */
function layoutHomeIntro() {
    const home = qs('#home')
    const wordmark = qs('.wordmark', home)
    if (!wordmark) return
    const r = wordmark.getBoundingClientRect() // (el contenedor no lleva transform: su caja es el lugar final del logo)
    if (!r.width) return
    const scale = innerWidth < 720 ? 0.85 : LOGO_START_SCALE
    const centerY = innerHeight * LOGO_CENTER_Y
    home.style.setProperty('--lx', innerWidth / 2 - (r.left + r.width / 2) + 'px')
    home.style.setProperty('--ly', centerY - (r.top + r.height / 2) + 'px')
    home.style.setProperty('--ls', scale)
    home.style.setProperty('--tagY', centerY + (r.height * scale) / 2 + 30 + 'px')
}

steps.home = {
    stage: 0,
    w: 0,
    layout: () => {
        fovBoost.t = isNarrow() ? HOME_FOV_NARROW : HOME_FOV
        layoutHomePets()
        layoutHomeIntro()
    }, // al cambiar el tamano de la ventana
    enter() {
        setCameraMode('orbit')
        livingRoom.root.visible = true // la calle con las casas (la de la experiencia); la casa de cajas no se ve
        world.root.visible = false
        setDoorOpen(false, true)
        setBackground('day')
        fovBoost.t = isNarrow() ? HOME_FOV_NARROW : HOME_FOV
        fovBoost.v = fovBoost.t // el campo de vision ya empieza en su valor final (la camara no se mueve)
        lightDim.t = HOME_DIM
        lightDim.v = HOME_DIM
        const wrld = buildHomeWorld()
        wrld.group.visible = true
        // al principio no hay nadie: Cacao y despues Nube aparecen con un salto (ver HOME_DOG_AT y HOME_CAT_AT)
        dog.visible = cat.visible = false
        // tranquilos: con wag > 1.8 jadean (boca abierta y sonido); en la portada solo mueven la cola y se entretienen entre ellos
        setPetMood(dog, { wag: 1.5, eyes: 1.1 })
        setPetMood(cat, { wag: 1.4, eyes: 1.1 })
        layoutHomePets()
        // onda de luz que se abre en el suelo donde aparece cada mascota
        const spawnRing = (pet) => {
            const ring = new THREE.Mesh(
                new THREE.RingGeometry(0.5, 0.6, 56),
                new THREE.MeshBasicMaterial({
                    color: '#ffd27a',
                    transparent: true,
                    opacity: 0.9,
                    blending: THREE.AdditiveBlending,
                    side: THREE.DoubleSide,
                    depthWrite: false,
                    fog: false,
                }),
            )
            ring.rotation.x = -Math.PI / 2
            ring.position.set(pet.position.x, pet.position.y + 0.03, pet.position.z)
            ring.scale.setScalar(0.3)
            wrld.group.add(ring)
            wrld.rings.push({ ring, age: 0 })
        }
        // Lo que hacen Cacao y Nube con el texto ya en pantalla, en una vuelta que se repite: Cacao se lame la pata, despues
        // Nube, y al final Cacao ladra y Nube maulla (siempre juntos, mirando a la camara)
        const timers = []
        const play = [
            [0, () => groomPet(dog, 3.4)],
            [4.2, () => groomPet(cat, 3.4)],
            [9.2, () => {
                dog.userData.hop = 1
                dog.userData.bark = 1
                audio.bark()
                timers.push(
                    setTimeout(() => {
                        cat.userData.hop = 1
                        cat.userData.bark = 1
                        audio.meow()
                    }, 500),
                )
            }],
        ]
        let playT = 0
        let playNext = 0
        let dogIn = false
        let catIn = false
        // Al mover el mouse la pantalla se mueve un poco a los lados (la camara y, en la presentacion del logo, el texto): x e y van de -1 a 1
        const homeEl = qs('#home')
        const mouse = { x: 0, y: 0, sx: 0, sy: 0 }
        const onMove = (event) => {
            mouse.x = (event.clientX / innerWidth) * 2 - 1
            mouse.y = (event.clientY / innerHeight) * 2 - 1
        }
        addEventListener('pointermove', onMove)
        // Sonidos de la presentacion, a la par de la animacion del logo (css/08-inicio.css): letras, golpe de la huella, deditos y temblor.
        // (Solo suenan si el navegador ya dejo activar el audio; si no, la presentacion queda en silencio.)
        const cue = (seconds, fn) => timers.push(setTimeout(() => state.cur === 'home' && fn(), seconds * 1000))
        for (let i = 0; i < 8; i++) cue(0.62 + i * 0.085, () => audio.introTick(i))
        cue(1.85, () => audio.introThump())
        ;[2.28, 2.44, 2.6, 2.76].forEach((seconds, i) => cue(seconds, () => audio.introPop(i)))
        cue(3.7, () => audio.introQuake())
        // La camara empieza un poco atras y se acerca hasta la vista de la portada. Mira recto hacia la entrada (-x).
        // Pantalla ancha: la camara queda justo frente a las mascotas y el encuadre (no la camara) se corre a un lado con setViewOffset, asi las
        // mascotas se ven de frente pero quedan a la izquierda y el texto a la derecha.
        // Celular y tablet (angosta o vertical): el texto va abajo, asi que la camara se aleja lo necesario para que las mascotas quepan
        // enteras en el ancho de la pantalla y mira un poco mas abajo, para que queden arriba.
        const setCamera = (k) => {
            // (sin acercamiento: la camara solo se mueve un poco con el mouse)
            const tanHalf = Math.tan(((34 + fovBoost.t * 26) * Math.PI) / 360)
            const aspect = innerWidth / innerHeight
            const narrow = isNarrow()
            const fitDistance = Math.min(6, Math.max(1.9, 0.8 / (tanHalf * aspect))) // distancia a la que las mascotas ocupan ~75 % del ancho
            const sideDistance = Math.min(3.4, Math.max(1.6, PETS_SPAN / (2 * HOME_SPAN) / (tanHalf * aspect))) // y aqui ~42 % (pantalla ancha)
            const finalR = (narrow ? fitDistance : sideDistance) + 0.1
            const startR = finalR + (narrow ? 1.5 : 1.4)
            k = 1 // la camara queda en la vista de la portada (sin acercamiento); solo se mueve un poco con el mouse
            const r = startR + (finalR - startR) * k
            const halfHeight = (r - 0.1) * tanHalf
            setOrbit({
                theta: mouse.sx * 0.005, // (camara en +x mirando hacia -x, la casa)
                r,
                h: HOME_START.h + (HOME_FINAL.h - HOME_START.h) * k,
                tx: HOME_ENTRY.x,
                ty: narrow ? 0.25 - 0.5 * halfHeight : HOME_ENTRY.ty, // (celular: mira mas abajo y las mascotas suben, para que se vean enteras sobre el fondo oscuro del texto)
                tz: HOME_ENTRY.z,
                sx: -mouse.sx * 0.05, // movimiento ligero con el mouse: solo para dar interaccion
                sy: mouse.sy * 0.03,
                speed: 0,
                amp: 0,
                fit: false,
            })
            // corrimiento del encuadre: positivo = la escena se ve mas a la izquierda
            if (narrow) {
                if (camera.view && camera.view.enabled) camera.clearViewOffset()
            } else {
                camera.setViewOffset(innerWidth, innerHeight, (HOME_SIDE * innerWidth) / 2, 0, innerWidth, innerHeight)
            }
        }
        setCamera(0)
        let time = -HOME_DELAY
        state.curTick = (dt) => {
            time += dt
            const follow = Math.min(1, dt * 4)
            mouse.sx += (mouse.x - mouse.sx) * follow
            mouse.sy += (mouse.y - mouse.sy) * follow
            homeEl.style.setProperty('--mx', mouse.sx.toFixed(3))
            homeEl.style.setProperty('--my', mouse.sy.toFixed(3))
            setCamera(homeEase(time / HOME_DOLLY))
            // aparecen con un salto y una onda de luz
            if (!dogIn && time > HOME_DOG_AT) {
                dogIn = true
                popIn(dog)
                spawnRing(dog)
            }
            if (!catIn && time > HOME_CAT_AT) {
                catIn = true
                popIn(cat)
                spawnRing(cat)
            }
            // las ondas se abren y se apagan
            for (let i = wrld.rings.length - 1; i >= 0; i--) {
                const item = wrld.rings[i]
                item.age += dt
                const k = item.age / 1.3
                if (k >= 1) {
                    item.ring.removeFromParent()
                    item.ring.geometry.dispose()
                    item.ring.material.dispose()
                    wrld.rings.splice(i, 1)
                    continue
                }
                item.ring.scale.setScalar(0.3 * (1 + k * 3))
                item.ring.material.opacity = 0.9 * (1 - k) ** 2
            }
            // con el texto en pantalla, juegan entre ellos
            if (time > HOME_PLAY_FROM) {
                playT += dt
                while (playNext < play.length && playT >= play[playNext][0]) play[playNext++][1]()
                if (playT >= HOME_PLAY_EVERY) {
                    playT = 0
                    playNext = 0
                }
            }
        }
        state.curExit = () => {
            timers.forEach(clearTimeout)
            removeEventListener('pointermove', onMove)
            document.body.classList.remove('on-home')
            camera.clearViewOffset() // (se vuelve al encuadre normal)
            camera.updateProjectionMatrix()
            wrld.rings.forEach(({ ring }) => ring.removeFromParent())
            wrld.rings.length = 0
            dog.userData.groomDur = cat.userData.groomDur = 0
            dog.userData.groom = cat.userData.groom = 0
            dog.userData.faceTo = cat.userData.faceTo = null
            dog.visible = cat.visible = true
            wrld.group.visible = false
            fovBoost.t = 0
            lightDim.t = 1
        }
        qs('#home').classList.add('active')
        document.body.classList.add('on-home') // en el inicio no se ve el logo de la esquina (ya esta el grande)
        layoutHomeIntro() // (con #home ya visible, para poder medir)
        qs('#hud').hidden = false
    },
}

/**
 * INTRODUCCION ANIMADA, ultimo paso antes de entrar a la casa.
 * Vista frontal del vecindario: la camara es una persona que cruza la calle y camina por el jardin
 * hasta la puerta (la del .glb). Mientras camina, la informacion de la experiencia aparece como frases
 * sueltas en distintos lugares de la pantalla (content.start.beats). Al llegar aparece el boton:
 * al pulsarlo se reproduce la animacion de apertura de la puerta (hecha en Blender) y el recorrido
 * sigue hacia adentro sin corte (paso walk).
 */
const WALK_TIME = 13.8 // segundos que dura la caminata hasta la puerta (la ultima frase entra a los 9.8 s y se queda hasta llegar, ver content.start.beats)
// Camino (x, z en metros): en linea recta y de frente a la casa, desde la calle hasta 1.8 m de la puerta
// (la puerta esta en x 3.46, z -2). Calle en x 13..19, aceras en 11..13 y 19..21.
const INTRO_PATH = [
    { x: 14.5, z: -2 },
    { x: 5.3, z: -2 },
]
const DOOR_LOOK = [3.46, 1.05, -2]
const KNOB = new THREE.Vector3(3.53, 1.06, -2.3) // la manija de la puerta de entrada (en el .glb)
let openDoor = () => {} // abre la puerta (la manija o "Siguiente")
steps.start = {
    stage: 1, // la introduccion es el comienzo del "Antes"
    w: 0,
    prev: 'home',
    next: 'walk', // con Siguiente se salta (con fundido) al momento de ya estar dentro de la casa; la puerta se abre al tocar la manija
    enter() {
        session.greeted = false
        session.enterSmooth = false
        session.quizQ = null // al reiniciar la experiencia puede tocar otra pregunta del reto
        dog.visible = cat.visible = false // estan dentro de la casa: aparecen al abrir la puerta
        setCameraMode('fp')
        setDoorOpen(false, true)
        setPetMood(dog, {})
        setPetMood(cat, {})
        // La camara camina sola (como una persona): el scroll no interviene
        startTour({ path: INTRO_PATH, look: DOOR_LOOK, closeFrom: 0.85, lookDown: 0.6 })
        lockTour()

        const text = content.start
        const beats = text.beats
            .map(
                (b) =>
                    '<div class="beat' +
                    (b.hold ? ' hold' : '') +
                    '" style="--at:' +
                    b.at +
                    's;--dur:' +
                    b.dur +
                    's">' +
                    '<span class="line">' +
                    b.text +
                    '</span></div>',
            )
            .join('')
        const el = showDynamic('<div class="introfx">' + beats + '</div>')
        let opening = false
        openDoor = () => {
            if (opening) return
            opening = true
            audio.blip()
            audio.creak()
            qs('.introfx', el).classList.add('out')
            knobSpot?.remove()
            doorLabel?.remove() // al hacer clic en la manija desaparece el "Entra a casa"
            setDoorOpen(true) // se reproduce la animacion de la puerta hecha en Blender
            session.enterSmooth = true // el siguiente paso continua la camara sin corte
            // ya con la puerta abierta, adentro ladran y maullan a recibirte
            // las mascotas salen caminando a recibirte casi al mismo tiempo que se abre la puerta (ver PETS_AT en before.js)
            setTimeout(() => audio.bark(), 250)
            setTimeout(() => audio.meow(), 650)
            setTimeout(() => state.cur === 'start' && goTo('walk'), 900)
        }
        // La manija es el boton para entrar: se ilumina al pasar el cursor y al hacer clic abre la puerta
        const knobAnchor = new THREE.Object3D()
        knobAnchor.position.copy(KNOB)
        livingRoom.root.add(knobAnchor)
        let knobSpot = null
        let doorLabel = null // "Entra a casa", sobre la puerta (texto sin recuadro)
        const labelAnchor = new THREE.Object3D()
        labelAnchor.position.set(KNOB.x, 0.62, -2.0)
        livingRoom.root.add(labelAnchor)
        state.curExit = () => {
            clearTimeout(cardTimer)
            qs('#panel').hidden = true
            knobAnchor.removeFromParent()
            labelAnchor.removeFromParent()
            knobSpot?.remove()
            doorLabel?.remove()
            openDoor = () => {}
        }
        // Camina hasta la puerta (en silencio: adentro solo ladran y maullan cuando se abre la puerta)
        // Al llegar a la puerta: una tarjeta alegre abre la "Etapa 1" y, al continuar, aparecen el titulo y la manija
        const showDoor = () => {
            if (opening || knobSpot || state.cur !== 'start') return
            knobSpot = addHotspot({ cls: 'knob', aria: 'Abrir la puerta', anchor: knobAnchor, onClick: () => openDoor() })
            doorLabel = addHotspot({ cls: 'plain', label: 'Entra a casa', aria: 'Entra a casa', anchor: labelAnchor })
            doorLabel.classList.add('pop', 'door')
            audio.chime() // sonido suave: ya se puede entrar a la casa y empezar
        }
        let cardShown = false
        let cardTimer = null
        const showStageCard = () => {
            cardShown = true
            qs('.beat.hold', el)?.classList.add('gone') // la frase final se va justo cuando aparece la tarjeta
            const stage = text.stage
            const words = stage.text
                .split(' ')
                .map((w, i) => '<span style="--i:' + i + '">' + w + '</span>')
                .join(' ')
            const panel = showPanel({
                cls: 'center quakecard stagecard',
                html:
                    '<svg class="qline" viewBox="0 0 400 40" preserveAspectRatio="none" aria-hidden="true"><path pathLength="1" d="M0 20H110c12 0 14-12 26-12s14 24 26 24 14-12 26-12 14 8 26 8 14-4 26-4H400"/></svg>' +
                    '<span class="qkick">' +
                    stage.kick +
                    '</span><h2 class="qtitle">' +
                    stage.title +
                    '</h2><p class="qtext">' +
                    words +
                    '</p>',
                actions: [
                    {
                        label: stage.cta,
                        fn: () => {
                            panel.classList.add('leaving')
                            cardTimer = setTimeout(() => {
                                qs('#panel').hidden = true
                                showDoor()
                            }, 450)
                        },
                    },
                ],
            })
        }
        let time = 0
        state.curTick = (dt) => {
            time += dt
            if (!opening) tour.target = Math.min(1, time / WALK_TIME)
            if (!cardShown && tour.progress > 0.985 && !opening) showStageCard() // al dejar de caminar
        }
    },
}
