/**
 * OBJETOS 3D: mochila del kit, elementos del kit, sombra suave y burbuja de miedo.
 */
import * as THREE from 'three'
import { cylinder, ellipsoid, mesh, place, roundedBox } from '../helpers.js'
import { createBagFromModel, createKitItem, hasKitModel } from './kitGlb.js'

/** La maleta del modelo de Blender (kitGlb.js); si no cargo, la mochila de cajas redondeadas. */
export function createBackpack() {
    if (hasKitModel()) return createBagFromModel()
    let e = new THREE.Group(),
        t = '#4a8bdd',
        a = place(cylinder(0.62, 0.62, 1.35, t, 28), 0, 0.75, 0)
    a.scale.z = 0.62
    e.add(a)
    e.add(place(ellipsoid(0.62, t, 1, 0.62, 0.62), 0, 1.42, 0))
    e.add(place(ellipsoid(0.62, t, 1, 0.35, 0.62), 0, 0.1, 0))
    let o = place(cylinder(0.45, 0.45, 0.7, '#6aa5f0', 24), 0, 0.5, 0.33)
    o.scale.z = 0.4
    e.add(o)
    let s = place(cylinder(0.24, 0.24, 0.04, '#ffffff', 24), 0, 1.02, 0.4)
    s.rotation.x = Math.PI / 2
    e.add(s)
    e.add(place(roundedBox(0.3, 0.08, 0.03, 0.01, '#ff7a66'), 0, 1.02, 0.43))
    e.add(place(roundedBox(0.08, 0.3, 0.03, 0.01, '#ff7a66'), 0, 1.02, 0.43))
    let r = place(mesh(new THREE.TorusGeometry(0.16, 0.04, 8, 16, Math.PI), '#14305e'), 0, 1.78, 0)
    e.add(r)
    return e
}
export function createItem(kind) {
    if (hasKitModel()) return createKitItem(kind)
    let t = new THREE.Group()
    if (kind === 'water') {
        t.add(
            place(
                mesh(new THREE.CylinderGeometry(0.17, 0.17, 0.6, 20), '#cdeeff', {
                    transparent: true,
                    opacity: 0.85,
                }),
                0,
                0,
                0,
            ),
        )
        t.add(place(cylinder(0.155, 0.155, 0.42, '#6fd6f0', 20), 0, -0.08, 0))
        t.add(place(cylinder(0.1, 0.1, 0.08, '#dff5ff', 16), 0, 0.34, 0))
        t.add(place(cylinder(0.09, 0.09, 0.1, '#ff7a66', 16), 0, 0.42, 0))
    } else if (kind === 'food') {
        t.add(roundedBox(0.6, 0.75, 0.24, 0.08, '#ffc24d'))
        t.add(place(roundedBox(0.38, 0.32, 0.02, 0.02, '#ffffff'), 0, 0.05, 0.13))
        t.add(place(ellipsoid(0.07, '#8a5a33', 1, 0.9, 0.4), 0, 0.02, 0.15))
        ;[-1, 0, 1].forEach((a) =>
            t.add(place(ellipsoid(0.03, '#8a5a33', 1, 1, 0.4), a * 0.07, 0.11 + (a === 0 ? 0.03 : 0), 0.15)),
        )
    } else if (kind === 'aid') {
        t.add(roundedBox(0.78, 0.56, 0.3, 0.08, '#ffffff'))
        t.add(place(roundedBox(0.3, 0.08, 0.03, 0.01, '#ff7a66'), 0, 0, 0.16))
        t.add(place(roundedBox(0.08, 0.3, 0.03, 0.01, '#ff7a66'), 0, 0, 0.16))
        t.add(place(mesh(new THREE.TorusGeometry(0.14, 0.03, 8, 14, Math.PI), '#14305e'), 0, 0.28, 0))
    } else if (kind === 'leash') {
        t.add(mesh(new THREE.TorusGeometry(0.28, 0.05, 10, 24), '#ff7a66'))
        t.add(place(mesh(new THREE.TorusGeometry(0.13, 0.04, 10, 20), '#ff7a66'), 0.5, 0, 0))
        t.add(place(cylinder(0.025, 0.025, 0.3, '#14305e', 8), 0.29, 0, 0)).children[2].rotation.z =
            Math.PI / 2
    } else if (kind === 'doc') {
        t.add(roundedBox(0.66, 0.82, 0.06, 0.03, '#9cc9cc'))
        t.add(place(roundedBox(0.52, 0.66, 0.02, 0.01, '#ffffff'), 0, 0.05, 0.05))
        ;[0.2, 0.08, -0.04].forEach((a) =>
            t.add(place(roundedBox(0.34, 0.03, 0.01, 0.005, '#c9dbff'), 0, a, 0.07)),
        )
    } else {
        let a = cylinder(0.055, 0.055, 0.5, '#fff0d9', 12)
        a.rotation.z = Math.PI / 2
        t.add(a)
        ;[
            [-0.25, 0.06],
            [-0.25, -0.06],
            [0.25, 0.06],
            [0.25, -0.06],
        ].forEach((o) => t.add(place(ellipsoid(0.075, '#fff0d9'), o[0], o[1], 0)))
        t.add(place(ellipsoid(0.16, '#ff7a66'), 0.05, -0.32, 0.1))
    }
    return t
}
export function createShadowBlob(radius) {
    let t = document.createElement('canvas')
    t.width = t.height = 64
    let a = t.getContext('2d'),
        o = a.createRadialGradient(32, 32, 0, 32, 32, 32)
    o.addColorStop(0, 'rgba(20,48,94,.35)')
    o.addColorStop(1, 'rgba(20,48,94,0)')
    a.fillStyle = o
    a.fillRect(0, 0, 64, 64)
    let s = new THREE.Mesh(
        new THREE.PlaneGeometry(radius * 2, radius * 2),
        new THREE.MeshBasicMaterial({
            map: new THREE.CanvasTexture(t),
            transparent: true,
            depthWrite: false,
            // quien la coloca con place() la deja a ras del piso (y = 0): sin esto se mezclaba con la base y salian rayas
            polygonOffset: true,
            polygonOffsetFactor: -4,
            polygonOffsetUnits: -4,
        }),
    )
    s.renderOrder = 1
    s.rotation.x = -Math.PI / 2
    s.position.y = 0.02
    return s
}
/**
 * Sombra de contacto (oclusion ambiental falsa): una mancha oscura y suave bajo un mueble o una mascota, de w x d metros de lado
 * (la parte de abajo del objeto queda oscura y se desvanece hacia afuera). Se pega al piso con polygonOffset y no escribe
 * profundidad, asi no se mezcla con el suelo ni da rayas.
 */
const contactTextures = {}
export function createContactShadow(w, d, strength = 0.38, tight = false) {
    // tight: borde mas definido (para las patas de las mascotas, donde una sombra grande y difusa se ve exagerada)
    const key = tight ? 'tight' : 'soft'
    if (!contactTextures[key]) {
        const c = document.createElement('canvas')
        c.width = c.height = 128
        const g = c.getContext('2d')
        const grad = g.createRadialGradient(64, 64, 0, 64, 64, 64)
        grad.addColorStop(0, 'rgba(20,32,64,1)')
        grad.addColorStop(tight ? 0.3 : 0.5, tight ? 'rgba(20,32,64,0.75)' : 'rgba(20,32,64,0.9)')
        grad.addColorStop(1, 'rgba(20,32,64,0)')
        g.fillStyle = grad
        g.fillRect(0, 0, 128, 128)
        contactTextures[key] = new THREE.CanvasTexture(c)
    }
    const mesh = new THREE.Mesh(
        new THREE.PlaneGeometry(w, d),
        new THREE.MeshBasicMaterial({
            map: contactTextures[key],
            transparent: true,
            opacity: strength,
            depthWrite: false,
            polygonOffset: true,
            polygonOffsetFactor: -4,
            polygonOffsetUnits: -4,
        }),
    )
    mesh.rotation.x = -Math.PI / 2
    mesh.renderOrder = 1
    return mesh
}
export function createFearBubble() {
    let e = document.createElement('canvas')
    e.width = e.height = 128
    let t = e.getContext('2d')
    t.fillStyle = 'rgba(255,255,255,.95)'
    t.strokeStyle = '#ff7a66'
    t.lineWidth = 8
    t.beginPath()
    t.arc(64, 70, 38, 0, 7)
    t.fill()
    t.stroke()
    ;[
        [28, 44, 34, 12, 52, 34],
        [100, 44, 94, 12, 76, 34],
    ].forEach((o) => {
        t.beginPath()
        t.moveTo(o[0], o[1])
        t.lineTo(o[2], o[3])
        t.lineTo(o[4], o[5])
        t.closePath()
        t.fill()
        t.stroke()
    })
    t.fillStyle = '#14305e'
    t.beginPath()
    t.arc(50, 68, 5, 0, 7)
    t.arc(78, 68, 5, 0, 7)
    t.fill()
    let a = new THREE.Sprite(
        new THREE.SpriteMaterial({
            map: new THREE.CanvasTexture(e),
            transparent: true,
            depthTest: false,
        }),
    )
    a.scale.set(0.9, 0.9, 1)
    a.renderOrder = 10
    return a
}
