function floorTexture() {
    let e = document.createElement('canvas')
    e.width = 256
    e.height = 256
    let t = e.getContext('2d')
    t.fillStyle = '#e8d2ae'
    t.fillRect(0, 0, 256, 256)
    for (let o = 0; o < 8; o++) {
        t.fillStyle = o % 2 ? '#e2caa3' : '#ecd8b6'
        t.fillRect(0, o * 32, 256, 32)
        t.fillStyle = 'rgba(120,80,40,.22)'
        t.fillRect(0, o * 32, 256, 2)
        t.fillRect((o * 83) % 256, o * 32, 2, 32)
    }
    let a = new THREE.CanvasTexture(e)
    a.wrapS = a.wrapT = THREE.RepeatWrapping
    a.repeat.set(5, 3.6)
    return a
}
