/**
 * VECINDARIO alrededor de la casa del .glb, armado como una calle de barrio: casas pegadas unas a otras,
 * con la fachada sobre el anden (sin antejardin), anden de baldosa roja, calle angosta, poste de luz
 * con cables y tanques de agua en las terrazas. Todo es decorado (sin colisiones), solo en primera persona.
 *
 * Mapa (metros): la casa esta en x -2.2..6 y mira al este (+x); su reja da a la linea de fachada x = 6.
 *   x 6..8.2      anden            x 8.2..14      calle (corre a lo largo de z)
 *   x 14..16.2    anden de enfrente, con casas de enfrente (fachada en x = 16.2, miran al oeste)
 * Las casas vecinas tienen tres estilos, tomados de una foto de referencia:
 *   A  ladrillo rojo con porton de barras blancas, ventana de barras y banda de celosias arriba
 *   B  enchape de mosaico beige/naranja con garaje de listones blancos
 *   C  piedra gris con ventanal de vidrio azul y rejas de forja
 *   D  casa blanca de dos pisos (para variar el perfil de la calle)
 */
import * as THREE from 'three'
import { getMaterial } from './helpers.js'

// ---------------------------------------------------------------- utilidades
let seed = 7
const rand = () => {
    seed = (seed * 16807) % 2147483647 // aleatorio repetible: la calle siempre se ve igual
    return seed / 2147483647
}
const pick = (list) => list[Math.floor(rand() * list.length)]

/** Textura dibujada con canvas 2D, repetible. */
function canvasTexture(draw, size = 256) {
    const canvas = document.createElement('canvas')
    canvas.width = canvas.height = size
    draw(canvas.getContext('2d'), size)
    const tex = new THREE.CanvasTexture(canvas)
    tex.wrapS = tex.wrapT = THREE.RepeatWrapping
    tex.anisotropy = 4
    return tex
}
const TEX = {}
const textures = () => {
    if (TEX.brick) return TEX
    // ladrillo terracota de juntas beige (como la textura de referencia): ladrillos largos con el borde un poco biselado y cada uno de un tono
    TEX.brick = canvasTexture((g, s) => {
        g.fillStyle = '#bdb0a2' // mortero
        g.fillRect(0, 0, s, s)
        const rows = 10
        const cols = 3
        const rh = s / rows
        const cw = s / cols
        const tones = [[184, 112, 90], [194, 124, 98], [176, 104, 84], [166, 98, 80], [198, 134, 108]] // terracota apagado (poco saturado)
        for (let r = 0; r < rows; r++)
            for (let c = -1; c <= cols; c++) {
                const [R, G, B] = pick(tones)
                const k = 0.94 + rand() * 0.12
                const x = c * cw + (r % 2) * (cw / 2) + 3
                const y = r * rh + 3
                const w = cw - 6
                const h = rh - 6
                const grad = g.createLinearGradient(x, y, x, y + h)
                grad.addColorStop(0, `rgb(${(R * k * 1.06) | 0},${(G * k * 1.06) | 0},${(B * k * 1.06) | 0})`)
                grad.addColorStop(1, `rgb(${(R * k * 0.9) | 0},${(G * k * 0.9) | 0},${(B * k * 0.9) | 0})`)
                g.fillStyle = grad
                g.beginPath()
                g.roundRect(x, y, w, h, 5)
                g.fill()
                g.strokeStyle = 'rgba(255,225,200,0.28)' // luz del borde de arriba
                g.lineWidth = 1.5
                g.beginPath()
                g.moveTo(x + 5, y + 1.5)
                g.lineTo(x + w - 5, y + 1.5)
                g.stroke()
            }
    }, 512)
    TEX.mosaic = canvasTexture((g, s) => {
        const n = 16
        for (let y = 0; y < n; y++)
            for (let x = 0; x < n; x++) {
                g.fillStyle = pick(['#c99a6b', '#d8b48a', '#b98055', '#e0a56e', '#c4b09a', '#a8805a'])
                g.fillRect((x * s) / n + 1, (y * s) / n + 1, s / n - 2, s / n - 2)
            }
    })
    TEX.stone = canvasTexture((g, s) => {
        g.fillStyle = '#8f9094'
        g.fillRect(0, 0, s, s)
        let y = 0
        while (y < s) {
            const h = 14 + rand() * 12
            let x = -rand() * 30
            while (x < s) {
                const w = 30 + rand() * 42
                g.fillStyle = pick(['#c9c9c4', '#b6b7b3', '#d8d8d3', '#a9aaa6', '#bdbdb8'])
                g.fillRect(x + 1, y + 1, w - 2, h - 2)
                x += w
            }
            y += h
        }
    })
    // anden de baldosa beige (como la textura de piso de referencia): baldosas grandes de tonos apenas distintos, con la junta mas oscura
    TEX.sidewalk = canvasTexture((g, s) => {
        g.fillStyle = '#b89d82' // junta
        g.fillRect(0, 0, s, s)
        const n = 2
        for (let y = 0; y < n; y++)
            for (let x = 0; x < n; x++) {
                const px = (x * s) / n + 3
                const py = (y * s) / n + 3
                const size = s / n - 6
                const grad = g.createLinearGradient(px, py, px + size, py + size)
                const base = pick(['#dcc4a8', '#d3b99c', '#e0cbb0', '#cdb294'])
                grad.addColorStop(0, base)
                grad.addColorStop(1, pick(['#cfb596', '#d8c0a4', '#c9ad8e']))
                g.fillStyle = grad
                g.fillRect(px, py, size, size)
            }
    }, 512)
    return TEX
}
/** Material con textura repetida segun el tamano real de la superficie (metros). */
function texturedMaterial(key, w, h, tileSize) {
    const tex = textures()[key].clone()
    tex.needsUpdate = true
    tex.repeat.set(w / tileSize, h / tileSize)
    return new THREE.MeshStandardMaterial({ map: tex, roughness: 0.92, metalness: 0 })
}
/** Caja sin sombras (el decorado no debe ensombrecer la casa principal). */
function box(w, h, d, color) {
    const m = new THREE.Mesh(
        new THREE.BoxGeometry(w, h, d),
        typeof color === 'string' ? getMaterial(color) : color,
    )
    return m
}
const at = (obj, x, y, z) => (obj.position.set(x, y, z), obj)

// ---------------------------------------------------------------- piezas de fachada (plano de fachada en x = 0, hacia +x)
const WHITE = '#f4f6fa'
const DARK = '#1b2438'

/** Ventana con marco blanco y barras: horizontales (barsH) o verticales (barsV). */
function addWindow(g, { z, y, w, h, barsH = 0, barsV = 0, glass = DARK }) {
    g.add(at(box(0.1, h + 0.16, w + 0.16, WHITE), 0.05, y, z))
    g.add(at(box(0.1, h, w, glass), 0.07, y, z))
    for (let i = 1; i <= barsH; i++)
        g.add(at(box(0.12, 0.05, w, WHITE), 0.1, y - h / 2 + (h * i) / (barsH + 1), z))
    for (let i = 1; i <= barsV; i++)
        g.add(at(box(0.12, h, 0.045, WHITE), 0.1, y, z - w / 2 + (w * i) / (barsV + 1)))
}
/** Porton de garaje: marco blanco con barras horizontales o listones verticales. */
function addGate(g, { z, w, h, vertical = false }) {
    g.add(at(box(0.08, h, w, DARK), 0.04, h / 2, z))
    g.add(at(box(0.12, h, 0.08, WHITE), 0.1, h / 2, z - w / 2))
    g.add(at(box(0.12, h, 0.08, WHITE), 0.1, h / 2, z + w / 2))
    g.add(at(box(0.12, 0.08, w, WHITE), 0.1, h, z))
    if (vertical) {
        const n = Math.round(w / 0.17)
        for (let i = 0; i < n; i++)
            g.add(at(box(0.1, h - 0.1, 0.1, WHITE), 0.12, h / 2, z - w / 2 + 0.1 + (i * (w - 0.2)) / (n - 1)))
        g.add(at(box(0.1, 0.1, w, WHITE), 0.13, 0.4, z))
    } else {
        const n = Math.round(h / 0.27)
        for (let i = 0; i < n; i++)
            g.add(at(box(0.11, 0.06, w, WHITE), 0.11, 0.18 + (i * (h - 0.3)) / (n - 1), z))
        g.add(at(box(0.12, h, 0.06, WHITE), 0.1, h / 2, z)) // division de las dos hojas
    }
}
function addMeterBox(g, z, y = 1.2) {
    g.add(at(box(0.14, 0.55, 0.32, WHITE), 0.07, y, z))
    g.add(at(box(0.15, 0.2, 0.16, '#9aa1ad'), 0.075, y + 0.08, z))
}
function addLouvers(g, w, y) {
    g.add(at(box(0.1, 0.32, w - 0.3, DARK), 0.05, y, 0))
    g.add(at(box(0.12, 0.04, w - 0.3, WHITE), 0.1, y + 0.18, 0))
    g.add(at(box(0.12, 0.04, w - 0.3, WHITE), 0.1, y - 0.18, 0))
    const n = Math.floor((w - 0.5) / 0.2)
    for (let i = 0; i < n; i++) g.add(at(box(0.1, 0.3, 0.07, WHITE), 0.11, y, -(w - 0.5) / 2 + i * 0.2))
}
/** Tanque de agua negro sobre la terraza. */
function addTank(g, x, z, roofY) {
    const tank = new THREE.Mesh(new THREE.CylinderGeometry(0.45, 0.45, 1.1, 14), getMaterial('#2b3040'))
    tank.position.set(x, roofY + 1, z)
    g.add(tank)
    ;[-0.3, 0.3].forEach((dz) => g.add(at(box(0.08, 0.5, 0.08, '#6b7280'), x, roofY + 0.3, z + dz)))
}

// ---------------------------------------------------------------- casas
// Proporciones de la casa de la experiencia (static/casa3.glb): pared de 2.55 m, puerta de 2.1 x 1.0 m,
// ventanas de 1.25 m de alto con el borde de abajo a 0.6 m del piso.
const FLOOR_H = 2.55
const DOOR_H = 2.1
const DOOR_W = 1
const WIN_H = 1.25
const WIN_Y = 0.6 + WIN_H / 2
const STYLES = {
    A: { w: 6.6, floors: 1 },
    B: { w: 5.2, floors: 1 },
    C: { w: 6.6, floors: 1 },
    D: { w: 6, floors: 2 },
}

/**
 * Casa con la fachada en x = 0 mirando a +x y el cuerpo hacia -x. Ocupa z -w/2..w/2.
 */
/** Cuerpos de las casas de los lados (casi transparentes solo cuando se esta dentro de la casa: ver setSideHouseGhost). */
const ghostMaterials = []
/** Materiales del vecindario que llevan un brillo propio (luz general de afuera): quakeEffects.js les pone la intensidad cada cuadro. */
export const neighborhoodGlow = []
let ghostK = 0
/** k = 1: las casas de los lados se ven a traves (adentro de la casa); k = 0: opacas (afuera). Cambia poco a poco. */
export function setSideHouseGhost(on, dt) {
    ghostK += (((on ? 1 : 0) - ghostK) * Math.min(1, dt * 4))
    ghostMaterials.forEach((m) => {
        m.opacity = 1 - 0.9 * ghostK
        m.depthWrite = ghostK < 0.5
    })
}

function makeHouse(style, ghost = false) {
    const { w, floors } = STYLES[style]
    const g = new THREE.Group()
    const H = floors === 2 ? FLOOR_H * 2 + 0.2 : FLOOR_H // mismas alturas que la casa de la experiencia
    const depth = 8.2

    // cuerpo (las casas de los lados de la casa principal son casi transparentes: asi se ve la luz que entra por las ventanas laterales)
    const body = at(
        box(
            depth,
            H,
            w,
            ghost
                ? (ghostMaterials[ghostMaterials.push(new THREE.MeshStandardMaterial({ color: '#e9e4dc', transparent: true, opacity: 1, roughness: 0.9 })) - 1])
                : '#e9e4dc',
        ),
        -depth / 2,
        H / 2,
        0,
    )
    if (ghost) body.renderOrder = 2
    g.add(body)
    // plano de fachada con la textura del estilo
    const material =
        style === 'A'
            ? texturedMaterial('brick', w, H, 1.2)
            : style === 'B'
              ? texturedMaterial('mosaic', w, H, 1)
              : style === 'C'
                ? texturedMaterial('stone', w, H, 1.4)
                : getMaterial('#f1ece4')
    const facade = new THREE.Mesh(new THREE.PlaneGeometry(w, H).rotateY(Math.PI / 2), material)
    facade.position.set(0.01, H / 2, 0)
    g.add(facade)
    // terraza con antepecho
    g.add(at(box(depth + 0.2, 0.2, w + 0.1, '#cfd3da'), -depth / 2, H + 0.1, 0))
    g.add(
        at(
            box(0.18, 0.4, w + 0.1, style === 'B' ? '#c9a77c' : style === 'C' ? '#b6b7b3' : WHITE),
            0.02,
            H + 0.3,
            0,
        ),
    )

    if (style === 'A') {
        addLouvers(g, w, H - 0.22)
        addGate(g, { z: -w / 2 + 1.55, w: 2.6, h: DOOR_H })
        addMeterBox(g, 0.55)
        addWindow(g, { z: w / 2 - 1.75, y: WIN_Y, w: 1.9, h: WIN_H, barsH: 3 })
        addTank(g, -2.5, 0.8, H + 0.2)
    } else if (style === 'B') {
        addWindow(g, { z: -w / 2 + 0.95, y: WIN_Y, w: 1.4, h: WIN_H, barsV: 7 })
        addMeterBox(g, -0.25, 1.1)
        addGate(g, { z: w / 2 - 1.5, w: 2.4, h: DOOR_H, vertical: true })
        addTank(g, -3, -0.5, H + 0.2)
    } else if (style === 'C') {
        // ventanal de vidrio azul con rejas de forja
        const wz = 0.2
        g.add(at(box(0.1, WIN_H + 0.16, 4.4, WHITE), 0.05, WIN_Y, wz))
        g.add(at(box(0.1, WIN_H, 4.24, '#2a4fa8'), 0.08, WIN_Y, wz))
        for (let i = 0; i <= 4; i++) g.add(at(box(0.12, WIN_H, 0.05, DARK), 0.12, WIN_Y, wz - 2.1 + i * 1.05))
        ;[-1.05, 1.05].forEach((dz) => {
            const ring = new THREE.Mesh(new THREE.TorusGeometry(0.5, 0.035, 8, 24), getMaterial(DARK))
            ring.rotation.y = Math.PI / 2
            ring.position.set(0.13, WIN_Y, wz + dz)
            g.add(ring)
        })
        g.add(at(box(0.14, 0.5, 0.6, '#b6b3ab'), 0.07, 0.55, w / 2 - 0.9)) // caja de contadores
        g.add(at(box(0.14, DOOR_H, DOOR_W, '#cfd3da'), 0.07, DOOR_H / 2, -w / 2 + 0.6)) // puerta
    } else {
        // casa blanca de dos pisos
        ;[WIN_Y, WIN_Y + FLOOR_H + 0.1].forEach((y) => {
            addWindow(g, { z: -w / 4, y, w: 1.6, h: WIN_H, barsV: 3, glass: '#7fa6d6' })
            addWindow(g, { z: w / 4, y, w: 1.6, h: WIN_H, barsV: 3, glass: '#7fa6d6' })
        })
        g.add(at(box(0.5, 0.12, w, '#cfd3da'), 0.25, FLOOR_H + 0.05, 0)) // losa del segundo piso
        g.add(at(box(0.14, DOOR_H, DOOR_W, '#cfd3da'), 0.07, DOOR_H / 2, 0)) // puerta
    }
    return g
}

/** Fila de casas contiguas a lo largo de z. */
function row(parent, { x, face, zStart, dir, styles, ghost = 0 }) {
    let z = zStart
    styles.forEach((style, i) => {
        const w = STYLES[style].w
        const house = makeHouse(style, i < ghost) // las primeras ghost casas son transparentes
        house.position.set(x, 0, z + (dir * w) / 2)
        house.rotation.y = face === 1 ? 0 : Math.PI
        parent.add(house)
        z += dir * w
    })
}

/** Poste de luz de concreto con cables. */
function makePole(parent, x, z, z2) {
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.2, 9, 10), getMaterial('#aeb2b8'))
    pole.position.set(x, 4.5, z)
    parent.add(pole)
    parent.add(at(box(0.12, 0.12, 1.8, '#6b7280'), x, 8.3, z))
    parent.add(at(box(0.12, 0.12, 1.4, '#6b7280'), x, 7.7, z))
    // cables hasta el siguiente poste
    ;[-0.7, 0, 0.7].forEach((off) => {
        const len = Math.abs(z2 - z)
        const cable = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, len, 4), getMaterial('#1b2438'))
        cable.rotation.x = Math.PI / 2
        cable.position.set(x + off * 0.3, 8.2 - Math.abs(off) * 0.3, (z + z2) / 2)
        parent.add(cable)
    })
}

export function buildNeighborhood(parent) {
    const flat = (w, d, material, x, y, z) => {
        const p = new THREE.Mesh(new THREE.PlaneGeometry(w, d), material)
        p.rotation.x = -Math.PI / 2
        p.position.set(x, y, z)
        p.receiveShadow = true
        parent.add(p)
    }
    // calle angosta y andenes de baldosa roja con sardinel
    flat(5.8, 160, getMaterial('#6d7280'), 11.1, 0.005, 0)
    const walk = (x) => {
        const m = texturedMaterial('sidewalk', 2.2, 160, 1.6)
        const top = new THREE.Mesh(new THREE.PlaneGeometry(2.2, 160), m)
        top.rotation.x = -Math.PI / 2
        top.position.set(x, 0.165, 0)
        parent.add(top)
        parent.add(at(box(2.2, 0.16, 160, '#cfd3da'), x, 0.08, 0))
    }
    walk(7.1)
    walk(15.1)
    parent.add(at(box(0.18, 0.2, 160, '#e4e8f0'), 8.3, 0.1, 0)) // sardinel
    parent.add(at(box(0.18, 0.2, 160, '#e4e8f0'), 13.9, 0.1, 0))

    // misma acera que la casa principal: casas vecinas pegadas a ambos lados (fachada en x = 6)
    row(parent, {
        x: 6,
        face: 1,
        zStart: 3.07,
        dir: 1,
        styles: ['B', 'A', 'C', 'D', 'B', 'A', 'C', 'B', 'D', 'A'],
        ghost: 2,
    })
    row(parent, {
        x: 6,
        face: 1,
        zStart: -3.07,
        dir: -1,
        styles: ['A', 'C', 'B', 'D', 'A', 'B', 'C', 'A', 'D', 'B'],
        ghost: 2,
    })
    // casas de enfrente (fachada en x = 16.2, miran al oeste)
    row(parent, {
        x: 16.2,
        face: -1,
        zStart: -34,
        dir: 1,
        styles: ['C', 'B', 'A', 'D', 'B', 'C', 'A', 'B', 'D', 'A', 'C'],
    })

    // luz general de afuera: un brillo propio en todo el vecindario (calle, andenes y casas), sin tocar el interior de la casa principal
    const mark = (material) => {
        if (!material.isMeshStandardMaterial || material.userData.glow) return material
        const own = ghostMaterials.includes(material) ? material : material.clone() // (los cuerpos transparentes se conservan: son los que cambia setSideHouseGhost)
        own.userData.glow = true
        own.emissive.copy(own.color)
        if (own.map) own.emissiveMap = own.map
        own.emissiveIntensity = 0
        neighborhoodGlow.push(own)
        return own
    }
    parent.traverse((o) => {
        if (o.isMesh && o.material && !Array.isArray(o.material)) o.material = mark(o.material)
    })

    // postes de luz con cables, como en la foto
    makePole(parent, 7.9, -7, 12)
    makePole(parent, 7.9, 12, 31)
    makePole(parent, 14.3, 2, -17)
}
