/**
 * CONTROLES: teclado, botones de sonido/musica, joystick tactil,
 * arrastre del raton y resize.
 */
import { audio } from '../audio/audio.js'
import { state } from '../core/state.js'
import { clamp, qs, qsa } from '../core/utils.js'
import { goTo, navGo, playStartWipe, steps, transitionTo } from '../steps/navigation.js'
import { triggerInteract } from '../systems/interaction.js'
import { showCam } from '../systems/camera.js'
import { joystick, keys, player } from '../systems/player.js'
import { nudgeTour, tour } from '../systems/scrollTour.js'
import { canvas, resize } from '../three/renderer.js'

// El panel de ajustes del caminar (F2) solo existe en desarrollo, no en la pagina publicada
if (import.meta.env.DEV) import('./walkTuner.js')

// ---- Recorrido por scroll: rueda, flechas/espacio y deslizar en pantalla ----
addEventListener(
    'wheel',
    (e) => {
        if (!tour.active) return
        e.preventDefault()
        // deltaMode: 0 = pixeles (mouse y trackpad), 1 = lineas, 2 = paginas
        nudgeTour(e.deltaMode === 2 ? e.deltaY * innerHeight : e.deltaMode === 1 ? e.deltaY * 16 : e.deltaY)
    },
    { passive: false },
)
addEventListener('pointermove', (e) => {
    tour.mx = (e.clientX / innerWidth) * 2 - 1
    tour.my = (e.clientY / innerHeight) * 2 - 1
})
const TOUR_KEYS = { ArrowDown: 140, PageDown: 400, Space: 400, ArrowUp: -140, PageUp: -400 }

// las flechas siempre avanzan el recorrido (tambien despues de hacer clic en un boton); la barra espaciadora solo si no hay un boton enfocado
const canScrollWithKey = (e) => {
    const tag = document.activeElement && document.activeElement.tagName
    if (/^(INPUT|TEXTAREA|SELECT)$/.test(tag)) return false
    return e.code !== 'Space' || (tag !== 'BUTTON' && tag !== 'A')
}
addEventListener('keydown', (e) => {
    if (tour.active && TOUR_KEYS[e.code] !== undefined && canScrollWithKey(e)) {
        e.preventDefault()
        nudgeTour(TOUR_KEYS[e.code])
        return
    }
    {
        keys.add(e.code)
        // (interactuar es solo con el clic en el boton "Revisar": no hay tecla E)
        if (
            (state.mode === 'fp' || state.mode === 'tp') &&
            ['Space', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].indexOf(e.code) >= 0
        ) {
            e.preventDefault()
        }
    }
})
addEventListener('keyup', (e) => keys.delete(e.code))
addEventListener('blur', () => keys.clear())
qs('#prompt .btn').addEventListener('click', triggerInteract)
qs('#navBack').addEventListener('click', () => navGo('back'))
qs('#navNext').addEventListener('click', () => navGo('next'))
// Las etapas de la linea de tiempo son botones: llevan al primer paso de esa etapa
// Inicio vuelve a la portada; "Antes" empieza en la introduccion ("ahora comienza el simulacro...")
const STAGE_ENTRY = ['home', 'start', 'quakeIntro', 'despIntro', 'close']
qsa('#stages button').forEach((button, stage) =>
    button.addEventListener('click', () => {
        const current = steps[state.cur]
        if (!current || state.cur === 'home' || state.cur === STAGE_ENTRY[stage]) return
        audio.blip()
        transitionTo(STAGE_ENTRY[stage], undefined, undefined, true)
    }),
)
// La musica empieza desde la portada: se prepara al cargar y suena con el primer toque, tecla o rueda en la pagina
// (los navegadores no dejan sonar antes de eso). El boton de musica se maneja aparte.
const unlockAudio = (event) => {
    if (event.target.closest && event.target.closest('#musicBtn')) return
    audio.init()
    ;['pointerdown', 'keydown', 'wheel', 'touchstart'].forEach((name) => removeEventListener(name, unlockAudio, true))
}
;['pointerdown', 'keydown', 'wheel', 'touchstart'].forEach((name) =>
    addEventListener(name, unlockAudio, { capture: true, passive: true }),
)
qs('#musicBtn').addEventListener('click', () => {
    let e = audio.toggleMusic()
    renderMusicIcon(e)
})
function renderMusicIcon(on) {
    let t = qs('#musicBtn')
    t.setAttribute('aria-pressed', on)
    t.innerHTML =
        '<svg viewBox="0 0 24 24"><path d="M9 18V6l10-2v12"/><circle cx="6.500" cy="18" r="2.500"/><circle cx="16.500" cy="16" r="2.500"/>' +
        (on ? '' : '<path d="M3 3l18 18"/>') +
        '</svg>'
}
renderMusicIcon(audio.musicOn) // empieza activada
// Pantalla completa: el boton alterna entre entrar y salir (se oculta si el navegador no lo permite, p. ej. iPhone)
const fullscreenBtn = qs('#fsBtn')
if (document.fullscreenEnabled || document.webkitFullscreenEnabled) {
    const isFull = () => !!(document.fullscreenElement || document.webkitFullscreenElement)
    const renderFullscreenIcon = () => {
        const on = isFull()
        fullscreenBtn.setAttribute('aria-pressed', on)
        fullscreenBtn.setAttribute('aria-label', on ? 'Salir de pantalla completa' : 'Pantalla completa')
        fullscreenBtn.title = on ? 'Salir de pantalla completa' : 'Pantalla completa'
        fullscreenBtn.innerHTML = on
            ? '<svg viewBox="0 0 24 24"><path d="M9 4v5H4M15 4v5h5M9 20v-5H4M15 20v-5h5"/></svg>'
            : '<svg viewBox="0 0 24 24"><path d="M4 9V4h5M20 9V4h-5M4 15v5h5M20 15v5h-5"/></svg>'
    }
    fullscreenBtn.addEventListener('click', () => {
        const root = document.documentElement
        if (isFull()) (document.exitFullscreen || document.webkitExitFullscreen).call(document)
        else (root.requestFullscreen || root.webkitRequestFullscreen).call(root)
    })
    ;['fullscreenchange', 'webkitfullscreenchange'].forEach((name) => document.addEventListener(name, renderFullscreenIcon))
    renderFullscreenIcon()
} else {
    fullscreenBtn.hidden = true
}
document.addEventListener('visibilitychange', () => {
    let e = audio.ctx
    if (e) {
        if (document.hidden) {
            e.suspend()
        } else if (audio.on) {
            e.resume()
        }
    }
})
qs('#startBtn').addEventListener('click', (event) => {
    audio.init()
    audio.blip()
    playStartWipe(event.currentTarget)
})
;(function () {
    let e = qs('#stick'),
        t = qs('i', e),
        a = null,
        o = (r) => {
            let i = e.getBoundingClientRect(),
                n = (r.clientX - i.left - i.width / 2) / (i.width / 2),
                d = (r.clientY - i.top - i.height / 2) / (i.height / 2),
                u = Math.hypot(n, d) || 1,
                h = Math.min(1, u)
            joystick.x = (n / u) * h
            joystick.y = (d / u) * h
            t.style.transform = 'translate(' + joystick.x * 36 + 'px,' + joystick.y * 36 + 'px)'
        }
    e.addEventListener('pointerdown', (r) => {
        a = r.pointerId
        e.setPointerCapture(a)
        o(r)
    })
    e.addEventListener('pointermove', (r) => {
        if (r.pointerId === a) {
            o(r)
        }
    })
    let s = (r) => {
        if (r.pointerId === a) {
            a = null
            joystick.x = joystick.y = 0
            t.style.transform = ''
        }
    }
    e.addEventListener('pointerup', s)
    e.addEventListener('pointercancel', s)
})()
;(function () {
    let e = null
    canvas.addEventListener('pointerdown', (a) => {
        e = {
            x: a.clientX,
            y: a.clientY,
            id: a.pointerId,
        }
        canvas.setPointerCapture(a.pointerId)
        if (state.onDragStart) state.onDragStart()
    })
    canvas.addEventListener('pointermove', (a) => {
        if (!e || a.pointerId !== e.id) return
        let o = a.clientX - e.x,
            s = a.clientY - e.y
        e.x = a.clientX
        e.y = a.clientY
        if (tour.active) {
            // Pantallas tactiles: deslizar verticalmente avanza el recorrido (no hay rueda).
            // Con raton, la camara sigue al puntero (ver scrollTour.js).
            if (a.pointerType === 'touch') {
                nudgeTour(-s * 2)
            }
        } else if (state.mode === 'fp') {
            player.yaw -= o * 0.005
            player.pitch = clamp(player.pitch - s * 0.004, -0.9, 0.9)
        } else if (state.mode === 'orbit') {
            // la camara orbital se puede girar arrastrando (tamanos): cada paso decide que hacer con el arrastre
            if (state.onDrag) state.onDrag(o, s)
        } else if (state.mode === 'show' || state.mode === 'stage') {
            // algunos pasos (el kit) usan el arrastre para girar un objeto y no la escena entera
            // arrastrar nunca gira a las mascotas: solo se mueve la camara (rastreo) o el objeto que se esta viendo (kit)
            if (state.onDrag) state.onDrag(o, s)
            else if (showCam.camOrbit) state.showRot += o * 0.01
        }
    })
    let t = () => {
        e = null
        if (state.onDragEnd) state.onDragEnd()
    }
    canvas.addEventListener('pointerup', t)
    canvas.addEventListener('pointercancel', t)
})()
addEventListener('resize', () => {
    resize()
    if (state.cur === 'home') {
        steps.home.layout()
    }
})
