/**
 * PELAJE: matiz por vertice para que el color no se vea plano.
 * El perro y el gato se pintan por zonas (pelaje, orejas, patas...) con un solo color cada una; aqui ese color se
 * oscurece un poco en el lomo, se aclara en la panza y varia en parches suaves (como pelo real). El gato ademas lleva
 * rayitas en el lomo y las patas. Todo es color de vertice: no cuesta nada al dibujar.
 */
const clamp01 = (v) => Math.min(1, Math.max(0, v))
const smoothstep = (a, b, x) => {
    const t = clamp01((x - a) / (b - a))
    return t * t * (3 - 2 * t)
}

/** Parches suaves de -1 a 1 que dependen solo de la posicion (siempre iguales para el mismo vertice). */
function patches(x, y, z) {
    return Math.sin(x * 23.1 + z * 7.3) * Math.sin(y * 19.7 - x * 5.1) * Math.sin(z * 17.3 + y * 3.9)
}

/**
 * Devuelve el color [r, g, b] del vertice.
 * base = color de la zona (THREE.Color), zone = 'fur' | 'ear' | 'light' | ..., (x, y, z) y (nx, ny, nz) = posicion y normal.
 */
export function shadeFur(base, zone, kind, x, y, z, nx, ny, nz) {
    if (zone !== 'fur' && zone !== 'ear' && zone !== 'light') return [base.r, base.g, base.b]
    const p = patches(x, y, z)
    let r = base.r
    let g = base.g
    let b = base.b
    if (zone === 'light') {
        // zonas claras (panza, patas, hocico): casi blancas, con un tono calido muy leve en los parches
        const k = 1 + p * 0.03
        return [Math.min(1, r * k), Math.min(1, g * k * (1 - 0.01 * p)), Math.min(1, b * k * (1 - 0.04 * p))]
    }
    const up = Math.max(0, ny)
    const down = Math.max(0, -ny)
    // el lomo mas oscuro y mas saturado (baja el azul y el verde mas que el rojo); la panza y los costados bajos mas claros
    let k = 1 + p * 0.07 - up * 0.11 + down * 0.07
    let rk = k
    let gk = k - up * 0.02
    let bk = k - up * 0.07
    if (zone === 'ear') {
        // las orejas con el borde mas oscuro que el resto
        rk *= 0.96
        gk *= 0.92
        bk *= 0.9
    }
    if (kind === 'cat' && zone === 'fur') {
        // rayitas de gato atigrado: cruzan el lomo y bajan por los costados, desfasadas con un vaiven para que no sean rectas
        const wave = Math.sin(x * 34 + y * 11) * 0.9 + p * 0.6
        const stripe = smoothstep(0.62, 0.9, Math.sin(z * 62 + wave)) * smoothstep(-0.1, 0.55, ny + 0.45 * Math.abs(nx))
        const dark = 1 - stripe * 0.26
        rk *= dark
        gk *= dark * 0.97
        bk *= dark * 0.92
    }
    return [clamp01(r * rk), clamp01(g * gk), clamp01(b * bk)]
}
