/**
 * MALETA Y OBJETOS DEL KIT (modelo de Blender: static/maleta.glb).
 * El .glb trae la maleta (maletin, maletin.001 = tapa con su animacion, bolsillo, cierre) y los objetos
 * sueltos. Aqui se separan y se acomodan para que encajen con el resto de la experiencia:
 *   - createBagFromModel()  maleta con su tapa animada (mixer: kit.mixer / kit.openAction)
 *   - createKitItem(kind)   un objeto del kit: water, food, aid, leash, doc o toy
 * Las imagenes de static/kit/ se pegan a las tarjetas (carne de gato y de perro) y a la etiqueta de la lata.
 * Si el .glb no carga, se usan la mochila y los objetos de cajas redondeadas (props.js).
 */
import * as THREE from 'three'
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js'
import { standardizeMaterials } from '../helpers.js'

const BAG_HEIGHT = 1.9 // altura de la maleta en la escena (como la mochila anterior)

// Que objetos del .glb forman cada objeto del kit y su tamano (lado mas largo del conjunto). Las piezas de
// un mismo objeto conservan EXACTAMENTE la posicion y el giro relativos que tienen en el archivo.
// (en el archivo cada uno es un nodo con su animacion de salida; el orden es el de la animacion)
const ITEMS = {
    food: { nodes: ['latita'], size: 0.8 },
    doc: { nodes: ['idgato'], size: 1.05 }, // los dos carnes viven dentro de este nodo
    toy: { nodes: ['pelota'], size: 1.1 }, // pelota, manta y hueso viven dentro de este nodo
    water: { nodes: ['Cylinder'], size: 0.8 },
    aid: { nodes: ['Cube'], size: 0.85 },
    leash: { nodes: ['medalla'], size: 1.1 },
}
const BAG_NODES = ['bolsillo', 'cierre', 'maletin', 'maletin001']

const IMAGES = {
    banner: 'kit/banner-pets-food.jpg',
    cat: 'kit/id-gato.jpg',
    dog: 'kit/id-perro.jpg',
}

let model = null // { scene, clip, textures }

export const hasKitModel = () => !!model

const loadImage = (url) =>
    new Promise((resolve, reject) => {
        const img = new Image()
        img.onload = () => resolve(img)
        img.onerror = reject
        img.src = url
    })

/** Recorta una imagen en un canvas y la devuelve como textura (para UVs de glTF: sin voltear). */
function cropTexture(img, x, y, w, h, flipY = false) {
    const c = document.createElement('canvas')
    c.width = Math.round(w)
    c.height = Math.round(h)
    c.getContext('2d').drawImage(img, x, y, w, h, 0, 0, c.width, c.height)
    const t = new THREE.CanvasTexture(c)
    t.flipY = flipY
    t.anisotropy = 4
    return t
}

/**
 * Etiqueta de la lata: la etiqueta da la vuelta a toda la lata, asi que se repite la insignia "FOOD" del banner
 * (cuatro veces, repartidas alrededor) sobre el color de fondo del banner.
 */
function labelTexture(banner) {
    const crop = document.createElement('canvas')
    crop.width = 225
    crop.height = 210
    const cg = crop.getContext('2d')
    cg.drawImage(banner, 70, 425, 225, 210, 0, 0, 225, 210)
    const [r, g, b] = cg.getImageData(3, 3, 1, 1).data
    const c = document.createElement('canvas')
    c.width = 1024
    c.height = 256
    const ctx = c.getContext('2d')
    ctx.fillStyle = `rgb(${r},${g},${b})`
    ctx.fillRect(0, 0, c.width, c.height)
    // la etiqueta ocupa la mitad de arriba de la textura (v de 0 a 0.5) y da la vuelta a la lata (de ahi que la insignia se estire al doble de ancho para verse redonda)
    for (let i = 0; i < 4; i++) ctx.drawImage(crop, i * 256 + 8, 4, 240, 120)
    const t = new THREE.CanvasTexture(c)
    t.flipY = false
    t.anisotropy = 4
    return t
}

/**
 * Recorta el carne de la foto: busca el color que mas se repite en el centro (el fondo azul del carne) y se
 * queda con el rectangulo que ocupa. Asi se ignoran el fondo de la foto y las marcas de agua de abajo.
 * Las tarjetas del .glb piden la imagen volteada verticalmente (flipY).
 */
function cardTexture(img) {
    const c = document.createElement('canvas')
    c.width = img.width
    c.height = img.height
    const g = c.getContext('2d')
    g.drawImage(img, 0, 0)
    const d = g.getImageData(0, 0, c.width, c.height).data
    const buckets = new Map()
    for (let y = Math.floor(c.height * 0.2); y < c.height * 0.8; y += 2)
        for (let x = Math.floor(c.width * 0.2); x < c.width * 0.8; x += 2) {
            const i = (y * c.width + x) * 4
            const key = (d[i] >> 4) * 256 + (d[i + 1] >> 4) * 16 + (d[i + 2] >> 4)
            const e = buckets.get(key) || { n: 0, r: 0, g: 0, b: 0 }
            e.n++
            e.r += d[i]
            e.g += d[i + 1]
            e.b += d[i + 2]
            buckets.set(key, e)
        }
    const top = [...buckets.values()].sort((p, q) => q.n - p.n)[0]
    const ref = [top.r / top.n, top.g / top.n, top.b / top.n]
    // cuantos pixeles del color del carne hay en cada fila y columna: el carne es donde hay muchos
    // (un pixel suelto, como el borde de una letra, no cuenta)
    const rows = new Array(c.height).fill(0)
    const cols = new Array(c.width).fill(0)
    for (let y = 0; y < c.height; y++)
        for (let x = 0; x < c.width; x++) {
            const i = (y * c.width + x) * 4
            if (Math.abs(d[i] - ref[0]) + Math.abs(d[i + 1] - ref[1]) + Math.abs(d[i + 2] - ref[2]) < 36) {
                rows[y]++
                cols[x]++
            }
        }
    const span = (counts, min) => {
        const from = counts.findIndex((n) => n >= min)
        const to = counts.length - 1 - [...counts].reverse().findIndex((n) => n >= min)
        return [from, to]
    }
    const [x0, x1] = span(cols, c.height * 0.25)
    const [y0, y1] = span(rows, c.width * 0.25)
    if (x0 < 0 || y0 < 0 || x1 <= x0 || y1 <= y0) return cropTexture(img, 0, 0, img.width, img.height, true)
    return cropTexture(img, x0, y0, x1 - x0 + 1, y1 - y0 + 1, true)
}

export async function loadKitModel() {
    try {
        const base = import.meta.env.BASE_URL
        const gltf = await new GLTFLoader().loadAsync(base + 'maleta.glb')
        const [banner, cat, dog] = await Promise.all(
            [IMAGES.banner, IMAGES.cat, IMAGES.dog].map((u) => loadImage(base + u).catch(() => null)),
        )
        const textures = {}
        if (cat) textures.cat = cardTexture(cat)
        if (dog) textures.dog = cardTexture(dog)
        // etiqueta de la lata: la insignia "FOOD" del banner de abajo
        if (banner) textures.food = labelTexture(banner)
        standardizeMaterials(gltf.scene) // todo reacciona a las luces
        gltf.scene.traverse((o) => {
            if (!o.isMesh) return
            o.castShadow = true
            o.receiveShadow = true
            const mats = Array.isArray(o.material) ? o.material : [o.material]
            mats.forEach((m) => {
                if (m.name === 'id.001' && textures.cat) setMap(m, textures.cat)
                if (m.name === 'id' && textures.dog) setMap(m, textures.dog)
                if (m.name === 'etiqueta.002' && textures.food) setMap(m, textures.food)
                m.roughness = Math.max(m.roughness ?? 0.6, 0.55)
                m.metalness = Math.min(m.metalness ?? 0, 0.2)
            })
        })
        const byNode = {}
        gltf.animations.forEach((a) => (byNode[a.name.replace(/Action(\.\d+)?$/, '')] = a))
        model = { scene: gltf.scene, clip: byNode['maletin.001'] || byNode.maletin001 || null, clips: byNode }
        setupItemAnimations()
        computeLayout()
    } catch (error) {
        console.warn('No cargo static/maleta.glb: se usan los objetos de cajas.', error)
        model = null
    }
}

/**
 * Escala y lugar de cada objeto tal como estan en el archivo (vistos de frente, como en Blender):
 * todo se escala igual que la maleta (para que midan lo mismo respecto a ella), la maleta apoya en y = 0,
 * lo que en Blender queda a la derecha (+z) queda a la derecha en la escena (+x).
 */
/**
 * En el archivo cada objeto trae su animacion de salida: empieza dentro de la maleta y termina en su lugar. La
 * pose guardada en el nodo es la de dentro de la maleta, asi que aqui se pone cada nodo en su pose FINAL (la que
 * se ve en Blender cuando termina) y se guarda como sacar el objeto: kitAnim(kind).at(u, salida), u de 0 a 1.
 * (Se evalua a mano con los interpoladores y no con un mixer, porque un mixer devuelve el nodo a su pose inicial.)
 */
const interp = (track) => track.createInterpolant()
function setupItemAnimations() {
    model.anims = {}
    for (const [kind, spec] of Object.entries(ITEMS)) {
        const node = findNode(spec.nodes[0])
        const clip = model.clips[spec.nodes[0]]
        if (!node || !clip) continue
        const tr = {}
        clip.tracks.forEach((t) => (tr[t.name.split('.').pop()] = interp(t)))
        // lo que el nodo trae de fabrica, para las propiedades que la animacion no mueve (p. ej. la escala)
        const orig = { p: node.position.clone(), q: node.quaternion.clone(), s: node.scale.clone() }
        const t0 = Math.min(...clip.tracks.map((t) => t.times[0]))
        const t1 = clip.duration
        const at = (time, out) => {
            const p = tr.position?.evaluate(time)
            const q = tr.quaternion?.evaluate(time)
            const s = tr.scale?.evaluate(time)
            out.position.set(p ? p[0] : orig.p.x, p ? p[1] : orig.p.y, p ? p[2] : orig.p.z)
            if (q) out.quaternion.set(q[0], q[1], q[2], q[3])
            else out.quaternion.copy(orig.q)
            if (s) out.scale.set(s[0], s[1], s[2])
            else out.scale.copy(orig.s)
            return out
        }
        const end = at(t1, {
            position: new THREE.Vector3(),
            quaternion: new THREE.Quaternion(),
            scale: new THREE.Vector3(),
        })
        node.position.copy(end.position)
        node.quaternion.copy(end.quaternion)
        node.scale.copy(end.scale)
        model.anims[kind] = { t0, t1, at, end }
    }
    model.firstStart = Math.min(...Object.values(model.anims).map((a) => a.t0))
    model.scene.updateMatrixWorld(true)
}

function computeLayout() {
    const bag = boxOf(BAG_NODES.map(findNode).filter(Boolean))
    const k = BAG_HEIGHT / (bag.max.y - bag.min.y)
    const layout = {}
    for (const [kind, spec] of Object.entries(ITEMS)) {
        const c = boxOf(spec.nodes.map(findNode).filter(Boolean)).getCenter(new THREE.Vector3())
        layout[kind] = [c.z * k, (c.y - bag.min.y) * k, 0.2]
    }
    model.k = k
    model.layout = layout
}

/** Donde va cada objeto del kit respecto a la maleta (como en el archivo de Blender): [x, y, z]. */
export const kitLayout = (kind) => model.layout[kind]

function setMap(material, map) {
    material.map = map
    material.color.set('#ffffff')
    material.needsUpdate = true
}

const findNode = (name) => model.scene.getObjectByName(name)

/** Caja que envuelve varios nodos (en el espacio del .glb, sin mover nada). */
function boxOf(nodes) {
    const box = new THREE.Box3()
    nodes.forEach((n) => box.expandByObject(n))
    return box
}

/**
 * Junta clones de los nodos en un grupo centrado en el origen, de frente a +z (en el .glb el frente
 * mira a -x) y escalado para que su lado mas largo mida "size".
 */
function assemble(names, size, { alignBottom = false, k: forcedK } = {}) {
    const nodes = names.map(findNode).filter(Boolean)
    const box = boxOf(nodes)
    const center = box.getCenter(new THREE.Vector3())
    const dim = box.getSize(new THREE.Vector3())
    const holder = new THREE.Group()
    // Las piezas conservan su posicion original del archivo; el desplazamiento al centro va en un grupo
    // aparte. (Si se moviera cada pieza, la animacion de la tapa, que trae posiciones absolutas, la
    // dejaria fuera de su sitio.)
    const inner = new THREE.Group()
    nodes.forEach((n) => inner.add(n.clone()))
    inner.position.copy(center).negate()
    if (alignBottom) inner.position.y += dim.y / 2
    holder.add(inner)
    const k = forcedK ?? size / Math.max(dim.x, dim.y, dim.z)
    holder.rotation.y = Math.PI / 2
    holder.scale.setScalar(k)
    const outer = new THREE.Group()
    outer.add(holder)
    return { outer, holder, k, dim }
}

/** Maleta con su tapa animada. kit.openAction: la animacion de la tapa (0 cerrada .. 1 abierta). */
export function createBagFromModel() {
    const { outer, holder, k, dim } = assemble(BAG_NODES, BAG_HEIGHT * 1.0, { alignBottom: true })
    // assemble() escala por el lado mas largo; aqui se quiere que el ALTO sea BAG_HEIGHT
    holder.scale.setScalar(BAG_HEIGHT / dim.y)
    void k
    outer.userData.holder = holder
    if (model.clip) {
        const mixer = new THREE.AnimationMixer(holder)
        const action = mixer.clipAction(model.clip)
        action.timeScale = 0 // no avanza sola: la tapa sigue a setBagLid()
        action.play()
        outer.userData.mixer = mixer
        outer.userData.action = action
        outer.userData.duration = model.clip.duration
        mixer.update(0)
    }
    return outer
}

/** Cuanto dura la animacion de la tapa en el archivo (segundos). */
export const kitLidDuration = () => (model.clip ? model.clip.duration : 0)

/** Abre la tapa de la maleta: open = 0 (cerrada) .. 1 (abierta). */
export function setBagLid(bag, open) {
    const m = bag.userData.mixer
    if (!m) return
    bag.userData.action.time = Math.min(1, Math.max(0, open)) * bag.userData.duration
    m.update(0)
}

/**
 * Un objeto del kit. kind: water, food, aid, leash, doc o toy.
 * La animacion de salida del archivo se reproduce TAL CUAL (mismas posiciones, giros y escalas, mismos tiempos)
 * con un AnimationMixer sobre el nodo: item.userData.kitAnim.setTime(t) pone la animacion en el segundo t de la
 * linea de tiempo del archivo (t0 = cuando empieza a moverse este objeto, t1 = cuando termina).
 */
export function createKitItem(kind) {
    const spec = ITEMS[kind]
    const { outer, holder } = assemble(spec.nodes, spec.size, { k: model.k }) // misma escala que la maleta
    const clip = model.clips[spec.nodes[0]]
    const anim = model.anims[kind]
    if (clip && anim) {
        const inner = holder.children[0]
        const mixer = new THREE.AnimationMixer(inner)
        const action = mixer.clipAction(clip)
        action.timeScale = 0 // no avanza sola: la mueve setTime()
        action.play()
        mixer.update(0)
        // Mientras el objeto esta dentro de la maleta se recorta con un plano a la altura de la boca (todo lo
        // que queda por debajo no se dibuja), asi no se sale por las paredes. kitAnim.clip es ese plano.
        const clipPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 1000) // constante 1000 = sin recorte
        inner.traverse((o) => {
            if (!o.isMesh) return
            ;(Array.isArray(o.material) ? o.material : [o.material]).forEach((m) => {
                m.clippingPlanes = [clipPlane]
                m.needsUpdate = true
            })
        })
        outer.userData.kitAnim = {
            t0: anim.t0,
            t1: anim.t1,
            clip: clipPlane,
            tClear: anim.t1, // segundo del archivo en que ya salio de la maleta (se calcula en computeClear)
            setTime(time) {
                action.time = Math.min(clip.duration, Math.max(0, time))
                mixer.update(0)
            },
        }
        outer.userData.kitAnim.setTime(0)
        // Calcula en que segundo el objeto ya salio POR COMPLETO de la maleta: cuando toda su caja queda por encima de la boca
        // o toda ella queda fuera de la maleta hacia un lado. (Antes bastaba el 75 % por encima de la boca o que su centro se
        // apartara: asi se dejaba de recortar con parte del objeto todavia dentro y atravesaba las paredes de la mochila.)
        // group = el objeto ya colocado en su lugar final.
        outer.userData.kitAnim.computeClear = (group, mouthY = 1.5, half = 0.75) => {
            const a = outer.userData.kitAnim
            const box = new THREE.Box3()
            group.updateMatrixWorld(true)
            let clear = a.t1
            for (let i = 0; i <= 120; i++) {
                const time = a.t0 + ((a.t1 - a.t0) * i) / 120
                a.setTime(time)
                group.updateMatrixWorld(true)
                box.setFromObject(group)
                if (
                    box.min.y >= mouthY - 0.02 ||
                    box.min.x > half ||
                    box.max.x < -half ||
                    box.min.z > half ||
                    box.max.z < -half
                ) {
                    clear = time
                    break
                }
            }
            a.tClear = clear
            a.setTime(0)
        }
    }
    return outer
}

/** Cuanto tarda en salir el ultimo objeto desde que sale el primero (para saber cuando termina todo). */
export const kitOutDuration = () =>
    Math.max(...Object.values(model.anims).map((a) => a.t1 - model.firstStart))
